# ASTRO-BHUDEB Astrology Engine
# Step 4: Julian Day + Planetary Positions

import swisseph as swe
from datetime import datetime, timezone, timedelta

# --------------------------------
# Read birth data
# --------------------------------

date_str = birth_data["date"]
time_str = birth_data["time"]

year, month, day = map(int, date_str.split("-"))
hour, minute, second = map(int, time_str.split(":"))

# Convert IST to UTC
utc_hour = hour - birth_data["timezone"]

# --------------------------------
# Julian Day
# --------------------------------

jd = swe.julday(
    year,
    month,
    day,
    utc_hour + minute / 60 + second / 3600
)

print("================================")
print("     ASTRO-BHUDEB CALCULATION")
print("================================")

print("Julian Day:", jd)

# --------------------------------
# Planet list
# --------------------------------

planets = {
    "Sun": swe.SUN,
    "Moon": swe.MOON,
    "Mars": swe.MARS,
    "Mercury": swe.MERCURY,
    "Jupiter": swe.JUPITER,
    "Venus": swe.VENUS,
    "Saturn": swe.SATURN,
    "Rahu": swe.MEAN_NODE
}

planet_positions = {}

print("\nPLANETARY POSITIONS")
print("----------------------------")

for name, planet in planets.items():

    position, ret = swe.calc_ut(jd, planet)

    longitude = position[0]

    planet_positions[name] = longitude

    print(f"{name:8s} : {longitude:.6f}°")

print("\nPlanetary calculation completed successfully.")

