DASHA_ORDER = [
    "Ketu",
    "Venus",
    "Sun",
    "Moon",
    "Mars",
    "Rahu",
    "Jupiter",
    "Saturn",
    "Mercury"
]

DASHA_YEARS = {
    "Ketu": 7,
    "Venus": 20,
    "Sun": 6,
    "Moon": 10,
    "Mars": 7,
    "Rahu": 18,
    "Jupiter": 16,
    "Saturn": 19,
    "Mercury": 17
}

# ------------------------------------------------------------
# STEP 9A
# Build Antardasha directly from existing Mahadasha data
# ------------------------------------------------------------

antardasha_list = []

for maha in mahadasha_list:

    maha_lord = maha["planet"]
    maha_start = maha["start"]
    maha_end = maha["end"]

    maha_days = (
        maha_end - maha_start
    ).total_seconds() / 86400.0

    start_index = DASHA_ORDER.index(maha_lord)

    current_start = maha_start

    for i in range(9):

        antara_lord = DASHA_ORDER[
            (start_index + i) % 9
        ]

        antara_days = (
            maha_days
            * DASHA_YEARS[antara_lord]
            / 120.0
        )

        current_end = (
            current_start
            + timedelta(days=antara_days)
        )

        if i == 8:
            current_end = maha_end

        antardasha_list.append({
            "maha": maha_lord,
            "planet": antara_lord,
            "start": current_start,
            "end": current_end
        })

        current_start = current_end


print("\nAntardasha periods generated:",
      len(antardasha_list))


# ------------------------------------------------------------
# STEP 9B
# Calculate Pratyantardasha
# ------------------------------------------------------------

pratyantardasha_list = []

for antara in antardasha_list:

    maha_lord = antara["maha"]
    antara_lord = antara["planet"]

    start_date = antara["start"]
    end_date = antara["end"]

    antara_days = (
        end_date - start_date
    ).total_seconds() / 86400.0

    start_index = DASHA_ORDER.index(antara_lord)

    current_start = start_date

    for i in range(9):

        praty_lord = DASHA_ORDER[
            (start_index + i) % 9
        ]

        praty_days = (
            antara_days
            * DASHA_YEARS[praty_lord]
            / 120.0
        )

        current_end = (
            current_start
            + timedelta(days=praty_days)
        )

        if i == 8:
            current_end = end_date

        pratyantardasha_list.append({
            "maha": maha_lord,
            "antara": antara_lord,
            "planet": praty_lord,
            "start": current_start,
            "end": current_end
        })

        current_start = current_end


