# ------------------------------------------------------------
# PLANET -> HOUSE MAPPING
# Uses previously calculated planet_positions and house cusps
# ------------------------------------------------------------

def normalize_degree(x):
    return x % 360.0


def house_from_degree(longitude, house_cusps):
    """
    Determine house from sidereal longitude and 12 house cusps.
    Handles zodiac wrap-around.
    """

    longitude = normalize_degree(longitude)

    for i in range(12):

        start = normalize_degree(house_cusps[i])

        end = normalize_degree(
            house_cusps[(i + 1) % 12]
        )

        if start < end:

            if start <= longitude < end:
                return i + 1

        else:

            if longitude >= start or longitude < end:
                return i + 1

    return None


# ------------------------------------------------------------
# Locate house cusp variable from previous calculation
# ------------------------------------------------------------

if "house_cusps" in globals():

    active_house_cusps = house_cusps

elif "house_cusp" in globals():

    active_house_cusps = house_cusp

elif "cusps" in globals():

    active_house_cusps = cusps

else:

    raise NameError(
        "House cusp data not found. "
        "Please run the Lagna / 12 House calculation first."
    )


# Convert dictionary/list cusp format if necessary

