# ------------------------------------------------------------
# Calculate EVENT SCORE for each Dasha level
# ------------------------------------------------------------

def planet_event_score(
    planet,
    event_rule
):

    score = 0

    # Planet itself
    if planet in event_rule["planets"]:
        score += 4

    # Planet's house
    if planet in planet_houses:

        house = planet_houses[planet]

        if house in event_rule["houses"]:
            score += 5

    return score


def event_score(
    maha,
    antara,
    praty,
    event_rule
):

    score = 0

    # Mahadasha lord
    score += planet_event_score(
        maha,
        event_rule
    ) * 2

    # Antardasha lord
    score += planet_event_score(
        antara,
        event_rule
    ) * 3

    # Pratyantardasha lord
    score += planet_event_score(
        praty,
        event_rule
    ) * 4

    return score


# ------------------------------------------------------------
# GENERATE EVENT TIMING CANDIDATES
# ------------------------------------------------------------

event_results = {}


for event_name, rule in EVENT_RULES.items():

    candidates = []

    for dasha in pratyantardasha_list:

        score = event_score(
            dasha["maha"],
            dasha["antara"],
            dasha["planet"],
            rule
        )

        if score > 0:

            candidates.append({

                "event": event_name,

                "maha": dasha["maha"],

                "antara": dasha["antara"],

                "praty": dasha["planet"],

                "start": dasha["start"],

                "end": dasha["end"],

                "score": score
            })


    # Highest score first
    candidates.sort(
        key=lambda x: x["score"],
        reverse=True
    )

    event_results[event_name] = candidates


# ------------------------------------------------------------
# DISPLAY TOP TIMING WINDOWS
