# ------------------------------------------------------------
# Find KP Sub Lord
# ------------------------------------------------------------

def get_kp_sub_lord(longitude):

    longitude = longitude % 360.0

    nakshatra_size = 360.0 / 27.0

    nak_index = int(
        longitude / nakshatra_size
    )

    if nak_index >= 27:
        nak_index = 26

    nakshatra = NAKSHATRAS[nak_index]

    star_lord = NAKSHATRA_LORD_SEQUENCE[
        nak_index % 9
    ]

    # Position inside Nakshatra
    start_degree = nak_index * nakshatra_size

    position = longitude - start_degree

    # Each Nakshatra is divided according to
    # Vimshottari proportional periods
    sub_sequence = []

    start_index = (
        NAKSHATRA_LORD_SEQUENCE.index(
            star_lord
        )
    )

    for i in range(9):

        lord = NAKSHATRA_LORD_SEQUENCE[
            (start_index + i) % 9
        ]

        proportion = (
            VIMSHOTTARI_YEARS[lord] / 120.0
        )

        sub_length = (
            nakshatra_size * proportion
        )

        sub_sequence.append(
            (lord, sub_length)
        )

    accumulated = 0.0

    sub_lord = star_lord
    sub_start = 0.0
    sub_end = nakshatra_size

    for lord, length in sub_sequence:

        next_accumulated = (
            accumulated + length
        )

        if position < next_accumulated:

            sub_lord = lord
            sub_start = accumulated
            sub_end = next_accumulated

            break

        accumulated = next_accumulated

    # Pada
    pada = int(
        position / (nakshatra_size / 4)
    ) + 1

    if pada > 4:
        pada = 4

    return {
        "nakshatra": nakshatra,
        "star_lord": star_lord,
        "sub_lord": sub_lord,
        "pada": pada,
        "position_in_nakshatra": position,
        "sub_start": sub_start,
        "sub_end": sub_end
    }


