def get_planet_houses(planet):

    houses = set()

    # --------------------------------------------------------
    # 1. Planet's own house
    # --------------------------------------------------------

    if planet in planet_positions and normalized_cusps:

        longitude = planet_positions[planet] % 360.0

        sorted_cusps = []

        for h in range(1, 13):
            if h in normalized_cusps:
                sorted_cusps.append(
                    (h, normalized_cusps[h] % 360.0)
                )

        for i in range(len(sorted_cusps)):

            house = sorted_cusps[i][0]
            start = sorted_cusps[i][1]

            if i < len(sorted_cusps) - 1:
                end = sorted_cusps[i + 1][1]
            else:
                end = sorted_cusps[0][1]

            if end <= start:
                end += 360.0

            test_longitude = longitude

            if test_longitude < start:
                test_longitude += 360.0

            if start <= test_longitude < end:
                houses.add(house)
                break

    return sorted(houses)


