# ------------------------------------------------------------
# EVENT JUDGMENT
# ------------------------------------------------------------

def judge_event(event_name):

    rule = EVENT_RULES[
        event_name
    ]

    positive = rule[
        "positive"
    ]

    negative = rule[
        "negative"
    ]

    matched_positive = set()
    matched_negative = set()

    supporting_houses = {}

    for house, data in cusp_significators.items():

        sub_houses = set(
            data["sub_houses"]
        )

        star_houses = set(
            data["star_houses"]
        )

        combined = (
            sub_houses |
            star_houses
        )

        pos = combined & positive
        neg = combined & negative

        matched_positive |= pos
        matched_negative |= neg

        supporting_houses[
            house
        ] = {
            "positive": sorted(pos),
            "negative": sorted(neg)
        }

    positive_score = len(
        matched_positive
    )

    negative_score = len(
        matched_negative
    )

    if positive_score > 0 and (
        positive_score >= negative_score
    ):

        verdict = "SUPPORTED"

    elif negative_score > positive_score:

        verdict = "WEAK / DELAYED"

    else:

        verdict = "MIXED"


    return {
        "event": event_name,
        "positive_houses": sorted(
            matched_positive
        ),
        "negative_houses": sorted(
            matched_negative
        ),
        "positive_score": positive_score,
        "negative_score": negative_score,
        "verdict": verdict,
        "supporting_houses": supporting_houses
    }


