def get_nakshatra_data(longitude):

    longitude = longitude % 360.0

    nakshatra_size = 360.0 / 27.0

    nak_index = int(
        longitude / nakshatra_size
    )

    if nak_index >= 27:
        nak_index = 26

    nak_name = NAKSHATRA_NAMES[nak_index]

    lord = NAKSHATRA_LORDS[
        nak_index % 9
    ]

    position_in_nakshatra = (
        longitude
        - nak_index * nakshatra_size
    )

    pada = int(
        position_in_nakshatra
        / (nakshatra_size / 4)
    ) + 1

    if pada > 4:
        pada = 4

    return {
        "nakshatra": nak_name,
        "lord": lord,
        "pada": pada,
        "index": nak_index
    }


