def get_event_significators(
    event_name
):

    required_houses = KP_EVENT_HOUSES[
        event_name
    ]

    result = []

    for planet, data in kp_planet_data.items():

        house = data["house"]

        star_lord = data["star_lord"]

        score = 0

        if house in required_houses:
            score += 5

        if star_lord in KP_PLANETS:

            star_data = kp_planet_data.get(
                star_lord
            )

            if star_data:

                if (
                    star_data["house"]
                    in required_houses
                ):
                    score += 4

        if score > 0:

            result.append({

                "planet": planet,

                "house": house,

                "star_lord": star_lord,

                "score": score
            })

    result.sort(
        key=lambda x: x["score"],
        reverse=True
    )

    return result


