# ------------------------------------------------------------
# PLANET → OCCUPIED HOUSE
# ------------------------------------------------------------

def planet_occupied_house(planet):

    if planet not in planet_positions:
        return None

    longitude = (
        planet_positions[planet] % 360
    )

    if not normalized_cusps:
        return None

    cusps = []

    for h in range(1, 13):

        if h in normalized_cusps:

            cusps.append(
                (
                    h,
                    normalized_cusps[h] % 360
                )
            )

    for i in range(len(cusps)):

        house = cusps[i][0]
        start = cusps[i][1]

        if i + 1 < len(cusps):
            end = cusps[i + 1][1]
        else:
            end = cusps[0][1]

        test = longitude

        if end <= start:
            end += 360

        if test < start:
            test += 360

        if start <= test < end:
            return house

    return None


# ------------------------------------------------------------
# PLANET SIGNIFICATOR HOUSES
# ------------------------------------------------------------

def kp_planet_significations(planet):

    houses = set()

    # Planet's occupied house
    occupied = planet_occupied_house(planet)

    if occupied:
        houses.add(occupied)

    # Star lord houses
    if planet in planet_kp_sub:

        star = planet_kp_sub[
            planet
        ].get("star_lord")

        if star:

            star_house = planet_occupied_house(
                star
            )

            if star_house:
                houses.add(
                    star_house
                )

    return houses


