# ------------------------------------------------
# Helper: safe house extraction
# ------------------------------------------------

def safe_house(data):
    if not isinstance(data, dict):
        return None

    h = data.get("house")

    try:
        h = int(h)
        if 1 <= h <= 12:
            return h
    except:
        pass

    return None


# ------------------------------------------------
# House ownership
# ------------------------------------------------

SIGN_LORDS = [
    "Mars",      # Aries
    "Venus",     # Taurus
    "Mercury",   # Gemini
    "Moon",      # Cancer
    "Sun",       # Leo
    "Mercury",   # Virgo
    "Venus",     # Libra
    "Mars",      # Scorpio
    "Jupiter",   # Sagittarius
    "Saturn",    # Capricorn
    "Saturn",    # Aquarius
    "Jupiter"    # Pisces
]


house_owners = {}

for house in range(1, 13):

    cusp = cusps[house - 1]

    sign_index = int((float(cusp) % 360.0) / 30.0)

    house_owners[house] = SIGN_LORDS[sign_index]


# ------------------------------------------------
# Build planet house ownership map
# ------------------------------------------------

planet_owned_houses = {}

for house, lord in house_owners.items():

    if lord not in planet_owned_houses:
        planet_owned_houses[lord] = []

    planet_owned_houses[lord].append(house)


# ------------------------------------------------
# Get occupied house safely
# ------------------------------------------------

def get_occupied_house(planet):

    if planet not in planet_kp_sub:
        return None

    return safe_house(planet_kp_sub[planet])

# ------------------------------------------------
# Get Star Lord
# ------------------------------------------------

def get_star_lord(planet):

    if planet not in planet_kp_sub:
        return None

    return planet_kp_sub[planet].get("star_lord")


# ------------------------------------------------
# Get Sub Lord
# ------------------------------------------------

def get_sub_lord(planet):

    if planet not in planet_kp_sub:
        return None

    return planet_kp_sub[planet].get("sub_lord")


# ------------------------------------------------
# KP significators
#
# Level 1 = Occupied house of planet
# Level 2 = Houses occupied by Star Lord
# Level 3 = Houses owned by Star Lord
# Level 4 = Houses occupied by Sub Lord
# Level 5 = Houses owned by Sub Lord
# ------------------------------------------------

def get_significator_houses(planet):

    if planet not in planet_kp_sub:
        return {
            "planet": planet,
            "occupied": [],
            "star_lord": None,
            "star_occupied": [],
            "star_owned": [],
            "sub_lord": None,
            "sub_occupied": [],
            "sub_owned": [],
            "all_houses": set(),
            "promotion_houses": set()
        }

    data = planet_kp_sub[planet]

    occupied_house = get_occupied_house(planet)

    star = get_star_lord(planet)

    sub = get_sub_lord(planet)

    # Planet's own occupied house
    occupied = set()

    if occupied_house is not None:
        occupied.add(occupied_house)

    # Star Lord
    star_occupied = set()
    star_owned = set()

    if star in planet_kp_sub: # Changed from planet_kp

        h = get_occupied_house(star)

        if h is not None:
            star_occupied.add(h)

    if star in planet_owned_houses:
        star_owned.update(planet_owned_houses[star])

    # Sub Lord
    sub_occupied = set()
    sub_owned = set()

    if sub in planet_kp_sub: # Changed from planet_kp

        h = get_occupied_house(sub)

        if h is not None:
            sub_occupied.add(h)

    if sub in planet_owned_houses:
        sub_owned.update(planet_owned_houses[sub])

    # Combined houses
    all_houses = (
        occupied |
        star_occupied |
        star_owned |
        sub_occupied |
        sub_owned
    )

    promotion_houses = all_houses & PROMOTION_HOUSES

    return {
        "planet": planet,
        "occupied": sorted(occupied),
        "star_lord": star,
        "star_occupied": sorted(star_occupied),
        "star_owned": sorted(star_owned),
        "sub_lord": sub,
        "sub_occupied": sorted(sub_occupied),
        "sub_owned": sorted(sub_owned),
        "all_houses": all_houses,
        "promotion_houses": promotion_houses
    }


# ================================================================
# CALCULATE ALL PLANETS
# ================================================================

KP_SIGNIFICATORS = {}

for planet in planet_kp_sub.keys():

    KP_SIGNIFICATORS[planet] = get_significator_houses(planet)


