for house in range(1, 13):

    cusp = float(cusps[house - 1]) % 360.0

    sign_index = int(cusp / 30.0)

    sign_index = max(0, min(sign_index, 11))

    house_owners[house] = SIGN_LORDS[sign_index]


# ------------------------------------------------
# PLANET OCCUPIED HOUSES
# ------------------------------------------------

planet_occupied = {}

for planet, data in planet_kp.items():

    h = data.get("house")

    try:
        h = int(h)
    except:
        h = None

    if h is not None and 1 <= h <= 12:
        planet_occupied[planet] = h


# ------------------------------------------------
# PLANET OWNED HOUSES
# ------------------------------------------------

planet_owned = {}

for house, lord in house_owners.items():

    planet_owned.setdefault(lord, []).append(house)


