planet_sub = {}

for planet, data in planet_kp.items():

    planet_sub[planet] = data.get("sub_lord")


# ================================================================
# FIND STAR OCCUPANTS
#
# Example:
# If Jupiter is Star Lord of Mars,
# Mars becomes an occupant/significator through Jupiter's star.
# ================================================================

star_occupants = {}

for planet in planet_kp.keys():

    star_occupants[planet] = []

    for other_planet, star in planet_star.items():

        if star == planet:

            star_occupants[planet].append(other_planet)


# ================================================================
# SIGNIFICATOR FUNCTION
# ================================================================

def kp_significators(planet):

    if planet not in planet_kp:

        return {
            "planet": planet,
            "own_occupied": [],
            "own_owned": [],
            "star_lord": None,
            "star_occupants": [],
            "star_houses": [],
            "sub_lord": None,
            "sub_houses": [],
            "all_houses": [],
            "promotion_houses": []
        }


    # ----------------------------
    # Planet's own houses
    # ----------------------------

    own_occupied = set()

    if planet in planet_occupied:
        own_occupied.add(
            planet_occupied[planet]
        )


    own_owned = set(
        planet_owned.get(planet, [])
    )


    # ----------------------------
    # Star Lord
    # ----------------------------

    star = planet_star.get(planet)


    occupants = star_occupants.get(
        star,
        []
    )


    # Houses occupied by planets
    # placed in the Star Lord's star
    star_houses = set()

    for p in occupants:

        if p in planet_occupied:

            star_houses.add(
                planet_occupied[p]
            )


        # Also include ownership
        for h in planet_owned.get(p, []):

            star_houses.add(h)


    # ----------------------------
    # Sub Lord
    # ----------------------------

    sub = planet_sub.get(planet)

    sub_houses = set()

    if sub in planet_occupied:

        sub_houses.add(
            planet_occupied[sub]
        )

    for h in planet_owned.get(sub, []):

        sub_houses.add(h)


    # ----------------------------
    # Combined
    # ----------------------------

    all_houses = (
        own_occupied |
        own_owned |
        star_houses |
        sub_houses
    )


    promotion_houses = (
        all_houses &
        PROMOTION_HOUSES
    )


    return {
        "planet": planet,
        "own_occupied": sorted(own_occupied),
        "own_owned": sorted(own_owned),
        "star_lord": star,
        "star_occupants": occupants,
        "star_houses": sorted(star_houses),
        "sub_lord": sub,
        "sub_houses": sorted(sub_houses),
        "all_houses": sorted(all_houses),
        "promotion_houses": sorted(promotion_houses)
    }


# ================================================================
# BUILD COMPLETE KP TABLE
# ================================================================

KP_FINAL = {}

for planet in planet_kp.keys():

    KP_FINAL[planet] = kp_significators(planet)


