# ------------------------------------------------------------
# House finder using 12 house cusps
# ------------------------------------------------------------

def get_house_from_cusps(longitude, cusps):
    longitude = longitude % 360

    for i in range(12):
        start = cusps[i] % 360
        end = cusps[(i + 1) % 12] % 360

        # Normal house interval
        if start < end:
            if start <= longitude < end:
                return i + 1

        # 360 -> 0 crossing
        else:
            if longitude >= start or longitude < end:
                return i + 1

    return None


