def normalize_houses(houses):
    if houses is None:
        return []
    if isinstance(houses, int):
        return [houses]
    if isinstance(houses, float):
        return [int(houses)]
    if isinstance(houses, (list, tuple, set)):
        return list(houses)
    return []

