# ------------------------------------------------
# FUNCTION:
# FULL KP SIGNIFICATION OF A PLANET
# ------------------------------------------------

def get_full_kp_houses(planet):

    houses = set()

    if planet is None:
        return sorted(houses)

    # 1. Planet's occupied house
    if planet in planet_occupied:
        houses.add(planet_occupied[planet])

    # 2. Planet's owned houses
    for h in planet_owned.get(planet, []):
        houses.add(h)

    # 3. Star Lord
    star = planet_star.get(planet)

    if star:

        # Planets occupying star lord's star
        for p in star_occupants.get(star, []):

            if p in planet_occupied:
                houses.add(planet_occupied[p])

            for h in planet_owned.get(p, []):
                houses.add(h)

    # 4. Sub Lord
    sub = planet_sub.get(planet)

    if sub:

        if sub in planet_occupied:
            houses.add(planet_occupied[sub])

        for h in planet_owned.get(sub, []):
            houses.add(h)

    return sorted(houses)


