TARGET_HOUSES = [2, 6, 10, 11]

PLANETS = [
    "Sun", "Moon", "Mars", "Mercury",
    "Jupiter", "Venus", "Saturn", "Rahu"
]


def clean_houses(value):
    """Convert house data safely into a set of integers."""
    if value is None:
        return set()

    if isinstance(value, (list, tuple, set)):
        result = set()
        for x in value:
            try:
                result.add(int(x))
            except:
                pass
        return result

    try:
        return {int(value)}
    except:
        return set()


def planet_chain(planet):
    """Return complete Own + Star + Sub house chain."""
    if not planet:
        return set()

    own = clean_houses(
        planet_owned_houses.get(planet, [])
    )

    star = clean_houses(
        planet_star_houses.get(planet, [])
    )

    sub = clean_houses(
        planet_sub_houses.get(planet, [])
    )

    return own | star | sub


