    star_chain = planet_chain(cusp_star)

    sub_match = sub_chain.intersection(TARGET_HOUSES)
    star_match = star_chain.intersection(TARGET_HOUSES)

    combined_chain = sub_chain | star_chain
    combined_match = combined_chain.intersection(TARGET_HOUSES)

    # This house is covered if its own target house
    # appears anywhere in the combined significator chain.
    covered = house in combined_match

    house_chain_results[house] = {
        "cusp_star": cusp_star,
        "cusp_sub": cusp_sub,
        "sub_chain": sorted(sub_chain),
        "star_chain": sorted(star_chain),
        "combined_chain": sorted(combined_chain),
        "combined_match": sorted(combined_match),
        "covered": covered
    }

    print()
    print(f"HOUSE {house}")
    print("Cusp Star Lord :", cusp_star)
    print("Cusp Sub Lord  :", cusp_sub)
    print("Sub-Lord Chain :", sorted(sub_chain))
    print("Star-Lord Chain:", sorted(star_chain))
    print("Combined Match :", sorted(combined_match))
    print("House Covered  :", covered)


