def safe_set(value):
    """
    Convert list / tuple / set / scalar into a clean set of integers.
    """
    if value is None:
        return set()

    if isinstance(value, (list, tuple, set)):
        result = set()
        for x in value:
            try:
                result.add(int(x))
            except:
                pass
        return result

    try:
        return {int(value)}
    except:
        return set()


