VIMSHOTTARI_YEARS = {
    "Ketu": 7,
    "Venus": 20,
    "Sun": 6,
    "Moon": 10,
    "Mars": 7,
    "Rahu": 18,
    "Jupiter": 16,
    "Saturn": 19,
    "Mercury": 17
}

DASHA_ORDER = [
    "Ketu",
    "Venus",
    "Sun",
    "Moon",
    "Mars",
    "Rahu",
    "Jupiter",
    "Saturn",
    "Mercury"
]

TARGET_HOUSES = {2, 6, 10, 11}
CORE_HOUSES = {6, 10, 11}


# ------------------------------------------------
# SAFE DATE CONVERSION
# ------------------------------------------------

def to_date(value):

    if isinstance(value, datetime):
        return value

    if hasattr(value, "to_pydatetime"):
        return value.to_pydatetime()

    return value


# ------------------------------------------------
# PLANET PROMOTION SCORE
# ------------------------------------------------

def planet_promotion_score(planet):

    info = planet_strength.get(planet, {})

    own = set(info.get("own_match", []))
    star = set(info.get("star_match", []))
    sub = set(info.get("sub_match", []))

    # Stronger weight for 6 / 10 / 11
    score = 0

    for house in own:
        if house in CORE_HOUSES:
            score += 4
        elif house == 2:
            score += 3

    for house in star:
        if house in CORE_HOUSES:
            score += 3
        elif house == 2:
            score += 2

    for house in sub:
        if house in CORE_HOUSES:
            score += 2
        elif house == 2:
            score += 1

    return score


# ------------------------------------------------
# PLANET SCORE TABLE
# ------------------------------------------------

print()
print("-" * 72)
print("PROMOTION PLANET SCORE")
print("-" * 72)

planet_promotion_scores = {}

for planet in DASHA_ORDER:

    score = planet_promotion_score(planet)

    planet_promotion_scores[planet] = score

    print(
        f"{planet:8s} | "
        f"Promotion Score = {score}"
    )


# ------------------------------------------------
# GENERATE ANTARDASHA
# ------------------------------------------------

def get_next_planet(planet):

    idx = DASHA_ORDER.index(planet)

    return DASHA_ORDER[(idx + 1) % len(DASHA_ORDER)]


def generate_antardashas(md):

    md_planet = md["planet"]

    md_start = to_date(md["start"])
    md_end = to_date(md["end"])

    total_days = (
        md_end - md_start
    ).total_seconds() / 86400.0

    md_years = VIMSHOTTARI_YEARS[md_planet]

    antardashas = []

    start_planet_index = DASHA_ORDER.index(md_planet)

    current_start = md_start

    for i in range(9):

        ad_planet = DASHA_ORDER[
            (start_planet_index + i) % 9
        ]

        ad_years = VIMSHOTTARI_YEARS[ad_planet]

        ad_fraction = ad_years / 120.0

        ad_days = total_days * ad_fraction

        current_end = current_start + timedelta(
            days=ad_days
        )

        # Never exceed Mahadasha boundary
        if current_end > md_end:
            current_end = md_end

        antardashas.append({
            "md": md_planet,
            "ad": ad_planet,
            "start": current_start,
            "end": current_end,
            "md_score": planet_promotion_scores.get(
                md_planet, 0
            ),
            "ad_score": planet_promotion_scores.get(
                ad_planet, 0
            )
        })

        current_start = current_end

    return antardashas


