# ------------------------------------------------
# Planet strength for promotion
# ------------------------------------------------

def promotion_strength(planet):
    houses = get_planet_target_houses(planet)

    score = 0

    # Core promotion houses
    if 10 in houses:
        score += 5

    if 11 in houses:
        score += 5

    if 6 in houses:
        score += 3

    # 2nd house = income / financial improvement
    if 2 in houses:
        score += 2

    return score


