# ------------------------------------------------
# Build AD windows from existing mahadasha_list
# ------------------------------------------------

for md in mahadasha_list:

    md_planet = md["planet"]
    md_start = md["start"]
    md_end = md["end"]

    md_score = promotion_planet_scores.get(md_planet, 0)

    # Only meaningful MDs
    if md_score == 0:
        continue

    # ------------------------------------------------
    # Generate Antara planets using standard Vimshottari
    # ------------------------------------------------

    antara_sequence = [
        "Ketu",
        "Venus",
        "Sun",
        "Moon",
        "Mars",
        "Rahu",
        "Jupiter",
        "Saturn",
        "Mercury"
    ]

    start_index = antara_sequence.index(md_planet)

    ordered_antara = (
        antara_sequence[start_index:]
        + antara_sequence[:start_index]
    )

    md_days = (md_end - md_start).days

    for antara_planet in ordered_antara:

        ad_score = promotion_planet_scores.get(antara_planet, 0)

        # Relative Vimshottari proportion
        antara_days = md_days * (
            {"Ketu":7, "Venus":20, "Sun":6, "Moon":10,
             "Mars":7, "Rahu":18, "Jupiter":16,
             "Saturn":19, "Mercury":17}[antara_planet]
            / 120
        )

        antara_start = md_start

        # Move past previous Antaras
        for previous_planet in ordered_antara:

            if previous_planet == antara_planet:
                break

            previous_days = md_days * (
                {"Ketu":7, "Venus":20, "Sun":6, "Moon":10,
                 "Mars":7, "Rahu":18, "Jupiter":16,
                 "Saturn":19, "Mercury":17}[previous_planet]
                / 120
            )

            antara_start += timedelta(days=previous_days)

        antara_end = antara_start + timedelta(days=antara_days)

        combined = md_score + ad_score

        # Promotion relevance
        if combined >= 15:
            level = "VERY STRONG"
        elif combined >= 10:
            level = "STRONG"
        elif combined >= 6:
            level = "MODERATE"
        else:
            level = "WEAK"

        antara_results.append({
            "md": md_planet,
            "ad": antara_planet,
            "start": antara_start,
            "end": antara_end,
            "md_score": md_score,
            "ad_score": ad_score,
            "combined": combined,
            "level": level
        })


