from datetime import datetime, timedelta

# ------------------------------------------------
# Vimshottari planet order + years
# ------------------------------------------------

VIM_ORDER = [
    "Ketu",
    "Venus",
    "Sun",
    "Moon",
    "Mars",
    "Rahu",
    "Jupiter",
    "Saturn",
    "Mercury"
]

VIM_YEARS = {
    "Ketu": 7,
    "Venus": 20,
    "Sun": 6,
    "Moon": 10,
    "Mars": 7,
    "Rahu": 18,
    "Jupiter": 16,
    "Saturn": 19,
    "Mercury": 17
}


# ------------------------------------------------
# Rotate sequence from a given lord
# ------------------------------------------------

def vim_sequence(start_planet):

    idx = VIM_ORDER.index(start_planet)

    return (
        VIM_ORDER[idx:] +
        VIM_ORDER[:idx]
    )


# ------------------------------------------------
# Generate Pratyantar periods inside an AD
# ------------------------------------------------

def generate_pd(ad_start, ad_end, ad_lord):

    sequence = vim_sequence(ad_lord)

    ad_days = (ad_end - ad_start).total_seconds() / 86400.0

    cursor = ad_start

    result = []

    for pd_lord in sequence:

        pd_days = (
            ad_days *
            VIM_YEARS[pd_lord] /
            120.0
        )

        pd_start = cursor
        pd_end = cursor + timedelta(days=pd_days)

        result.append({
            "pd": pd_lord,
            "start": pd_start,
            "end": pd_end
        })

        cursor = pd_end

    return result


