def get_kp_transit_info(longitude):

    longitude = float(longitude) % 360.0

    nak_size = 360.0 / 27.0
    pada_size = nak_size / 4.0

    longitude = longitude % 360.0

    index = int(longitude / nak_size)
    index = max(0, min(index, len(nakshatra_lords) - 1))

    within = longitude - index * nak_size

    within = max(
        0.0,
        min(within, nak_size - 1e-12)
    )

    star_lord = nakshatra_lords[index]

    pada = int(within / pada_size) + 1
    pada = max(1, min(pada, 4))
    return {
        "nak_index": index + 1,
        "star_lord": star_lord,
        "pada": pada,
        "within": within
    }

