# MOVED UP (ordering fix): these were originally defined much
# later in the file (near old line 8700+), but were already being
# CALLED here, causing:
#   NameError: name 'get_transit_longitude' is not defined
# Moved to before first use. Original later definitions left in
# place too (harmless identical redefinition, no behavior change).
# ------------------------------------------------------------

def datetime_to_jd(dt):

    if not isinstance(dt, datetime):
        raise TypeError("datetime_to_jd() requires datetime input")

    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)

    dt = dt.astimezone(timezone.utc)

    return swe.julday(
        dt.year,
        dt.month,
        dt.day,
        dt.hour + dt.minute / 60.0 + dt.second / 3600.0
    )


def get_transit_longitude(planet_id, dt):

    if not isinstance(dt, datetime):
        raise TypeError(
            "get_transit_longitude() requires datetime input"
        )

    jd = datetime_to_jd(dt)

    flags = swe.FLG_SWIEPH | swe.FLG_SIDEREAL

    xx, retflag = swe.calc_ut(
        jd,
        planet_id,
        flags
    )

    return float(xx[0]) % 360.0


