from datetime import datetime, timezone
import swisseph as swe

print("=" * 72)
print("STEP 18N-D1-FIX — CLEAN TRANSIT FUNCTION MAPPING")
print("=" * 72)

# ------------------------------------------------
# DATETIME -> JULIAN DAY
# ------------------------------------------------

def datetime_to_jd(dt):

    if not isinstance(dt, datetime):
        raise TypeError("datetime_to_jd() requires datetime input")

    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=timezone.utc)

    dt = dt.astimezone(timezone.utc)

    return swe.julday(
        dt.year,
        dt.month,
        dt.day,
        dt.hour + dt.minute / 60.0 + dt.second / 3600.0
    )


# ------------------------------------------------
# TRANSIT LONGITUDE
# Input  : planet_id, datetime
# Output : sidereal longitude
# ------------------------------------------------

def get_transit_longitude(planet_id, dt):

    if not isinstance(dt, datetime):
        raise TypeError(
            "get_transit_longitude() requires datetime input"
        )

    jd = datetime_to_jd(dt)

    flags = swe.FLG_SWIEPH | swe.FLG_SIDEREAL

    xx, retflag = swe.calc_ut(
        jd,
        planet_id,
        flags
    )

    return float(xx[0]) % 360.0


# ------------------------------------------------
# KP TRANSIT INFO
# IMPORTANT:
# Input = LONGITUDE ONLY
# ------------------------------------------------

def get_kp_transit_info(longitude):

    longitude = float(longitude) % 360.0

    nakshatra_size = 360.0 / 27.0
    pada_size = nakshatra_size / 4.0

    nak_index = int(longitude / nakshatra_size)

    nak_index = max(
        0,
        min(nak_index, 26)
    )

    within = longitude - nak_index * nakshatra_size

    within = max(
        0.0,
        min(within, nakshatra_size - 1e-12)
    )

    # STAR LORD
    star_lord = nakshatra_lords[nak_index]

    # SUB LORD
    dasha_order = [
        "Ketu",
        "Venus",
        "Sun",
        "Moon",
        "Mars",
        "Rahu",
        "Jupiter",
        "Saturn",
        "Mercury"
    ]

    dasha_years = {
        "Ketu": 7,
        "Venus": 20,
        "Sun": 6,
        "Moon": 10,
        "Mars": 7,
        "Rahu": 18,
        "Jupiter": 16,
        "Saturn": 19,
        "Mercury": 17
    }

    start_index = dasha_order.index(star_lord)

    sub_start = 0.0
    sub_lord = None
    sub_end = nakshatra_size

    for i in range(9):

        lord = dasha_order[
            (start_index + i) % 9
        ]

        sub_size = (
            nakshatra_size
            * dasha_years[lord]
            / 120.0
        )

        next_end = sub_start + sub_size

        if within < next_end:

            sub_lord = lord
            sub_end = next_end

            break

        sub_start = next_end

    if sub_lord is None:
        sub_lord = dasha_order[
            (start_index + 8) % 9
        ]

        sub_end = nakshatra_size

    # PADA
    pada = int(
        within / pada_size
    ) + 1

    pada = max(
        1,
        min(pada, 4)
    )

    return {
        "nak_index": nak_index + 1,
        "star_lord": star_lord,
        "sub_lord": sub_lord,
        "pada": pada,
        "within": within,
        "sub_start": sub_start,
        "sub_end": sub_end,
        "longitude": longitude
    }


