print("\nNATAL PROMOTION TARGET MAP")
print("-" * 72)

try:

    for planet, data in planet_significators.items():

        print(
            f"{planet:<10} -> {data}"
        )

except NameError:

    print("planet_significators variable not found.")


# ------------------------------------------------
# TRANSIT SUB-LORD SCAN
# ------------------------------------------------

print("\nTRANSIT SUB-LORD MATCHING")
print("-" * 72)

observations = []

current = START_DATE

while current <= END_DATE:

    for planet_name, planet_id in TRANSIT_PLANETS.items():

        try:

            longitude, kp_info = read_transit(
                planet_id,
                current
            )

            star_lord = kp_info.get("star_lord")
            pada = kp_info.get("pada")
            nak_index = kp_info.get("nak_index")

            observations.append({
                "date": current,
                "planet": planet_name,
                "longitude": longitude,
                "star_lord": star_lord,
                "pada": pada,
                "nak_index": nak_index
            })

        except Exception as e:

            print(
                current.strftime("%d-%m-%Y"),
                planet_name,
                "ERROR:",
                type(e).__name__,
                e
            )

    current += timedelta(days=1)


# ------------------------------------------------
# SUB-LORD -> NATAL HOUSE MATCH
# ------------------------------------------------

valid_matches = []

for obs in observations:

    sub_lord = None

    # Try existing KP information first
    if "sub_lord" in obs:
        sub_lord = obs["sub_lord"]

    # If get_kp_transit_info provides it
    if sub_lord is None:
        try:
            jd = datetime_to_jd(obs["date"])
            info = get_kp_transit_info(jd)

            sub_lord = info.get("sub_lord")

        except Exception:
            pass

    obs["sub_lord"] = sub_lord

    if sub_lord is None:
        continue

    # Natal significator lookup
    try:

        sig = planet_significators.get(
            sub_lord,
            []
        )

        if isinstance(sig, dict):

            houses = set(
                sig.get("houses", [])
            )

        else:

            houses = set(sig)

        matched = sorted(
            houses.intersection(TARGET_HOUSES)
        )

        if matched:

            valid_matches.append({
                **obs,
                "matched_houses": matched,
                "score": len(matched)
            })

    except Exception:
        pass


