# ------------------------------------------------
# VIMSHOTTARI ORDER
# ------------------------------------------------

VIMSHOTTARI_ORDER = [
    "Ketu",
    "Venus",
    "Sun",
    "Moon",
    "Mars",
    "Rahu",
    "Jupiter",
    "Saturn",
    "Mercury"
]

VIMSHOTTARI_YEARS = {
    "Ketu": 7,
    "Venus": 20,
    "Sun": 6,
    "Moon": 10,
    "Mars": 7,
    "Rahu": 18,
    "Jupiter": 16,
    "Saturn": 19,
    "Mercury": 17
}

TOTAL_DASHA_YEARS = 120.0

NAK_SIZE = 360.0 / 27.0


# ------------------------------------------------
# FIND KP SUB-LORD
# ------------------------------------------------

def get_kp_sub_lord(longitude):

    longitude = float(longitude) % 360.0

    nak_index = int(longitude / NAK_SIZE)

    nak_index = max(
        0,
        min(nak_index, 26)
    )

    within = longitude - (
        nak_index * NAK_SIZE
    )

    within = max(
        0.0,
        min(
            within,
            NAK_SIZE - 1e-12
        )
    )

    star_lord = nakshatra_lords[nak_index]

    # ------------------------------------------------
    # KP SUB-LORD SEQUENCE STARTS FROM STAR LORD
    # ------------------------------------------------

    start_index = VIMSHOTTARI_ORDER.index(
        star_lord
    )

    sub_lord = None
    sub_start = 0.0
    sub_end = 0.0

    for i in range(9):

        lord = VIMSHOTTARI_ORDER[
            (start_index + i) % 9
        ]

        sub_size = (
            NAK_SIZE
            * VIMSHOTTARI_YEARS[lord]
            / TOTAL_DASHA_YEARS
        )

        sub_end = sub_start + sub_size

        if within < sub_end:

            sub_lord = lord
            break

        sub_start = sub_end

    if sub_lord is None:

        sub_lord = VIMSHOTTARI_ORDER[
            (start_index + 8) % 9
        ]

        sub_end = NAK_SIZE

    return {
        "nak_index": nak_index + 1,
        "star_lord": star_lord,
        "sub_lord": sub_lord,
        "within": within,
        "sub_start": sub_start,
        "sub_end": sub_end
    }


# ------------------------------------------------
# COMBINED KP TRANSIT INFO
# ------------------------------------------------

def get_full_kp_transit_info(planet_id, dt):

    longitude = get_transit_longitude(
        planet_id,
        dt
    )

    jd = datetime_to_jd(dt)

    basic = get_kp_transit_info(jd)

    sub = get_kp_sub_lord(
        longitude
    )

    return {
        "longitude": longitude,
        "nak_index": sub["nak_index"],
        "star_lord": sub["star_lord"],
        "sub_lord": sub["sub_lord"],
        "pada": basic.get(
            "pada"
        ),
        "within": sub["within"]
    }


