# ------------------------------------------------------------
# 11. PLANET SIGNIFICATION
# ------------------------------------------------------------

def _houses(planet):

    return sorted(
        set(
            NATAL_TARGET_MAP.get(
                planet,
                []
            )
        ).intersection(
            PROMOTION_HOUSES
        )
    )


def _score(planet):

    houses = _houses(planet)

    score = sum(
        HOUSE_WEIGHT[h]
        for h in houses
    )

    return houses, score


