HOUSE_WEIGHT = {
    2:  1,   # supporting gain / material result
    6:  2,   # service / competition / employment
    10: 3,   # career / status
    11: 3    # gain / fulfilment
}

PROMOTION_HOUSES = {2, 6, 10, 11}


