# ------------------------------------------------
# 5. SAFE DATE PARSER
# ------------------------------------------------

def _to_date(value):

    if value is None:
        return None

    if isinstance(value, datetime):
        return value.date()

    if hasattr(value, "date"):
        try:
            return value.date()
        except:
            pass

    if isinstance(value, str):

        formats = [
            "%d-%m-%Y",
            "%Y-%m-%d",
            "%d/%m/%Y",
            "%Y/%m/%d"
        ]

        for fmt in formats:

            try:
                return datetime.strptime(
                    value.strip(),
                    fmt
                ).date()

            except:
                pass

    return None


# ------------------------------------------------
# 6. GENERIC DASHA ENTRY PARSER
# ------------------------------------------------

def _parse_dasha_entry(entry):

    planet = None
    start  = None
    end    = None

    if isinstance(entry, dict):

        planet = (
            entry.get("planet")
            or entry.get("lord")
            or entry.get("name")
            or entry.get("dasha")
        )

        start = (
            entry.get("start")
            or entry.get("start_date")
            or entry.get("from")
            or entry.get("begin")
        )

        end = (
            entry.get("end")
            or entry.get("end_date")
            or entry.get("to")
            or entry.get("finish")
        )

    elif isinstance(entry, (list, tuple)):

        if len(entry) >= 3:

            planet = entry[0]
            start  = entry[1]
            end    = entry[2]

    return {
        "planet": planet,
        "start": _to_date(start),
        "end":   _to_date(end)
    }


# ------------------------------------------------
# 7. FIND ACTIVE DASHA
# ------------------------------------------------

def _find_active_dasha(entries, dt):

    if not entries:
        return None

    target = dt.date()

    for entry in entries:

        x = _parse_dasha_entry(entry)

        if (
            x["planet"] is not None
            and x["start"] is not None
            and x["end"] is not None
        ):

            if x["start"] <= target <= x["end"]:
                return x

    return None


# ------------------------------------------------
# 8. PLANET -> SIGNIFICATION
# ------------------------------------------------

def _planet_score(planet):

    houses = NATAL_TARGET_MAP.get(
        planet,
        []
    )

    matched = sorted(
        set(houses).intersection(
            PROMOTION_HOUSES
        )
    )

    score = sum(
        HOUSE_WEIGHT[h]
        for h in matched
    )

    return matched, score


