    pd_houses, pd_score = _planet_score(
        pd_planet
    )


    # --------------------------------------------
    # Weighted hierarchy
    #
    # MD = background
    # AD = stronger timing
    # PD = strongest trigger
    # --------------------------------------------

    total_score = (
        md_score * 1
        + ad_score * 2
        + pd_score * 3
    )


    # --------------------------------------------
    # Count independent layers
    # --------------------------------------------

    active_layers = 0

    if md_score > 0:
        active_layers += 1

    if ad_score > 0:
        active_layers += 1

    if pd_score > 0:
        active_layers += 1


    # --------------------------------------------
    # Classification
    # --------------------------------------------

    if (
        pd_score >= 3
        and active_layers >= 2
        and total_score >= 12
    ):

        level = "HIGH"

    elif (
        pd_score > 0
        and active_layers >= 2
        and total_score >= 6
    ):

        level = "MEDIUM"

    elif total_score > 0:

        level = "LOW"

    else:

        level = "NONE"


    daily_results.append({

        "date": current,

        "MD": md_planet,
        "AD": ad_planet,
        "PD": pd_planet,

        "MD_houses": md_houses,
        "AD_houses": ad_houses,
        "PD_houses": pd_houses,

        "md_score": md_score,
        "ad_score": ad_score,
        "pd_score": pd_score,

        "total_score": total_score,

        "active_layers": active_layers,

        "level": level
    })

    current += timedelta(days=1)


