from datetime import datetime, timedelta
from dateutil.relativedelta import relativedelta

print("=" * 76)
print("D3 DASHA SOURCE REBUILD STARTED")
print("=" * 76)

# ------------------------------------------------------------
# 1. VERIFIED BIRTH INPUTS
# ------------------------------------------------------------

BIRTH_DT = datetime(1983, 12, 8, 15, 50)

DASHA_ORDER = [
    "Ketu",
    "Venus",
    "Sun",
    "Moon",
    "Mars",
    "Rahu",
    "Jupiter",
    "Saturn",
    "Mercury"
]

DASHA_YEARS = {
    "Ketu": 7,
    "Venus": 20,
    "Sun": 6,
    "Moon": 10,
    "Mars": 7,
    "Rahu": 18,
    "Jupiter": 16,
    "Saturn": 19,
    "Mercury": 17
}

# Birth MD = Sun
# Remaining Sun balance = 1.208 years
SUN_BALANCE_YEARS = 1.208


# ------------------------------------------------------------
# 2. HELPER
# ------------------------------------------------------------

def add_years_fraction(dt, years):
    """
    Add fractional Vimshottari years.
    Uses 365.2425 days/year for the fractional part.
    """
    whole = int(years)
    fraction = years - whole

    dt = dt + relativedelta(years=whole)
    dt = dt + timedelta(days=fraction * 365.2425)

    return dt


# ------------------------------------------------------------
# 3. BUILD MAHADASHA
# ------------------------------------------------------------

global_mahadasha_list = []

# Sun remaining balance
sun_end = add_years_fraction(
    BIRTH_DT,
    SUN_BALANCE_YEARS
)
global_mahadasha_list = []

# Compatibility alias
mahadasha_list = global_mahadasha_list

# Sun remaining balance
sun_end = add_years_fraction(
    BIRTH_DT,
    SUN_BALANCE_YEARS
)
# First record
global_mahadasha_list.append({
    "planet": "Sun",
    "start": BIRTH_DT,
    "end": sun_end,
    "years": SUN_BALANCE_YEARS
})

# Continue after Sun
current_start = sun_end

# Start AFTER Sun in Vimshottari order
sun_index = DASHA_ORDER.index("Sun")

for i in range(1, len(DASHA_ORDER)):

    planet = DASHA_ORDER[(sun_index + i) % len(DASHA_ORDER)]

    years = DASHA_YEARS[planet]

    current_end = add_years_fraction(
        current_start,
        years
    )

    global_mahadasha_list.append({
        "planet": planet,
        "start": current_start,
        "end": current_end,
        "years": years
    })

    current_start = current_end


# ------------------------------------------------------------
# 4. BUILD ANTARDASHA
# ------------------------------------------------------------

antara_source = []

for md in global_mahadasha_list:

    md_planet = md["planet"]
    md_start = md["start"]
    md_end = md["end"]

    md_total_years = DASHA_YEARS[md_planet]

    md_index = DASHA_ORDER.index(md_planet)

    ad_start = md_start

    for j in range(len(DASHA_ORDER)):

        ad_planet = DASHA_ORDER[
            (md_index + j) % len(DASHA_ORDER)
        ]

        # AD duration:
        # MD years × AD planet years / 120
        ad_years = (
            md_total_years
            * DASHA_YEARS[ad_planet]
            / 120.0
        )

        ad_end = add_years_fraction(
            ad_start,
            ad_years
        )

        # Don't allow floating calculation beyond MD
        if ad_end > md_end:
            ad_end = md_end

        antara_source.append({
            "MD": md_planet,
            "AD": ad_planet,
            "start": ad_start,
            "end": ad_end,
            "years": ad_years
        })

        ad_start = ad_end


# ------------------------------------------------------------
# 5. BUILD PRATYANTARDASHA
# ------------------------------------------------------------

pratyantardasha_list = []

for ad in antara_source:

    md_planet = ad["MD"]
    ad_planet = ad["AD"]

    ad_start = ad["start"]
    ad_end = ad["end"]

    md_years = DASHA_YEARS[md_planet]
    ad_years = DASHA_YEARS[ad_planet]

    ad_index = DASHA_ORDER.index(ad_planet)

    pd_start = ad_start

    for k in range(len(DASHA_ORDER)):

        pd_planet = DASHA_ORDER[
            (ad_index + k) % len(DASHA_ORDER)
        ]

        # PD duration:
        # AD duration × PD planet years / 120
        pd_years = (
            md_years
            * ad_years
            * DASHA_YEARS[pd_planet]
            / (120.0 * 120.0)
        )

        pd_end = add_years_fraction(
            pd_start,
            pd_years
        )

        if pd_end > ad_end:
            pd_end = ad_end

        pratyantardasha_list.append({
            "MD": md_planet,
            "AD": ad_planet,
            "PD": pd_planet,
            "start": pd_start,
            "end": pd_end,
            "years": pd_years
        })

        pd_start = pd_end


# ------------------------------------------------------------
# 6. COMPATIBILITY ALIASES
# ------------------------------------------------------------

# Existing notebook code may use different names.
md_source = global_mahadasha_list
ad_source = antara_source
pd_source = pratyantardasha_list

global_antardasha_list = antara_source
global_pratyantardasha_list = pratyantardasha_list


