# STEP 18N-D3-FINAL — SELF-CONTAINED, OUT-OF-ORDER-PROOF
# Replaces the old "TOP 20 DASHA DATES - FIXED RANKING" cell
# This cell ALWAYS rebuilds daily_results from scratch,
# so it can never KeyError on 'pd_score' again, no matter
# which earlier cells were or weren't run in this session.
# ============================================================

from datetime import datetime, date, timedelta

print("=" * 76)
print("STEP 18N-D3-FINAL — REBUILD + RANK (SAFE)")
print("=" * 76)

# ------------------------------------------------------------
# 1. CONFIG (idempotent — safe to redefine every run)
# ------------------------------------------------------------

PROMOTION_HOUSES = {2, 6, 10, 11}

HOUSE_WEIGHT = {2: 1, 6: 2, 10: 3, 11: 3}

NATAL_TARGET_MAP = {
    "Ketu":    [],
    "Venus":   [2],
    "Sun":     [6],
    "Moon":    [6],
    "Mars":    [],
    "Rahu":    [6],
    "Jupiter": [6],
    "Saturn":  [6, 10, 11],
    "Mercury": [6, 10, 11],
}

START_DATE = datetime(2026, 7, 12)
END_DATE   = datetime(2026, 11, 27)

CURRENT_MD = "Jupiter"
CURRENT_AD = "Venus"

DASHA_ORDER = [
    "Ketu", "Venus", "Sun", "Moon", "Mars",
    "Rahu", "Jupiter", "Saturn", "Mercury",
]

DASHA_YEARS = {
    "Ketu": 7, "Venus": 20, "Sun": 6, "Moon": 10, "Mars": 7,
    "Rahu": 18, "Jupiter": 16, "Saturn": 19, "Mercury": 17,
}

# ------------------------------------------------------------
# 2. SAFE HELPERS (self-contained, no dependency on
#    earlier cells' versions of these functions)
# ------------------------------------------------------------

def _as_date_safe(x):
    if x is None:
        return None
    if isinstance(x, datetime):
        return x.date()
    if isinstance(x, date):
        return x
    if isinstance(x, str):
        for fmt in ("%Y-%m-%d", "%d-%m-%Y", "%Y/%m/%d", "%d/%m/%Y"):
            try:
                return datetime.strptime(x.strip(), fmt).date()
            except ValueError:
                pass
    if hasattr(x, "date"):
        try:
            return x.date()
        except Exception:
            pass
    return None


def _entry_safe(e):
    if isinstance(e, dict):
        planet = e.get("planet") or e.get("lord") or e.get("name") or e.get("dasha")
        start = e.get("start") or e.get("start_date") or e.get("from") or e.get("begin")
        end = e.get("end") or e.get("end_date") or e.get("to") or e.get("finish")
        return {
            "planet": planet,
            "start": _as_date_safe(start),
            "end": _as_date_safe(end),
        }
    if isinstance(e, (list, tuple)) and len(e) >= 3:
        return {
            "planet": e[0],
            "start": _as_date_safe(e[1]),
            "end": _as_date_safe(e[2]),
        }
    return {"planet": None, "start": None, "end": None}


def _active_safe(entries, day):
    for raw in entries or []:
        e = _entry_safe(raw)
        if e["planet"] and e["start"] and e["end"] and e["start"] <= day <= e["end"]:
            return e
    return None


def _planet_score_safe(planet):
    houses = sorted(
        set(NATAL_TARGET_MAP.get(planet, [])).intersection(PROMOTION_HOUSES)
    )
    score = sum(HOUSE_WEIGHT[h] for h in houses)
    return houses, score


def _build_ad_from_md_safe(md_list):
    out = []
    for md_raw in md_list:
        md = _entry_safe(md_raw)
        if not md["planet"] or not md["start"] or not md["end"]:
            continue
        md_days = (md["end"] - md["start"]).days
        idx = DASHA_ORDER.index(md["planet"])
        cursor = md["start"]
        for i in range(9):
            p = DASHA_ORDER[(idx + i) % 9]
            days = md_days * DASHA_YEARS[p] / 120.0
            end = md["end"] if i == 8 else cursor + timedelta(days=days)
            out.append({"planet": p, "start": cursor, "end": end})
            cursor = end
    return out


def _build_pd_from_ad_safe(ad_list):
    out = []
    for ad_raw in ad_list:
        ad = _entry_safe(ad_raw)
        if not ad["planet"] or not ad["start"] or not ad["end"]:
            continue
        ad_days = (ad["end"] - ad["start"]).days
        idx = DASHA_ORDER.index(ad["planet"])
        cursor = ad["start"]
        for i in range(9):
            p = DASHA_ORDER[(idx + i) % 9]
            days = ad_days * DASHA_YEARS[p] / 120.0
            end = ad["end"] if i == 8 else cursor + timedelta(days=days)
            out.append({"planet": p, "start": cursor, "end": end})
            cursor = end
    return out

# ------------------------------------------------------------
# 3. GET / REBUILD DASHA SOURCES
#    (tolerant to whatever variable names exist in globals)
# ------------------------------------------------------------

md_list = (
    globals().get("mahadasha_list")
    or globals().get("global_mahadasha_list")
    or []
)

antara_source = (
    globals().get("antara_source")
    or globals().get("global_antardasha_list")
    or globals().get("antardasha_list")
    or []
)

if not antara_source and md_list:
    antara_source = _build_ad_from_md_safe(md_list)

pd_source = (
    globals().get("pd_source")
    or globals().get("global_pratyantardasha_list")
    or globals().get("pratyantardasha_list")
    or []
)

if not pd_source and antara_source:
    pd_source = _build_pd_from_ad_safe(antara_source)

print("MD records :", len(md_list))
print("AD records :", len(antara_source))
print("PD records :", len(pd_source))

if not antara_source:
    raise RuntimeError(
        "Antardasha source EMPTY — run the base Dasha Engine cell first."
    )

# ------------------------------------------------------------
# 4. REBUILD daily_results FROM SCRATCH — GUARANTEED pd_score
# ------------------------------------------------------------

daily_results = []
current = START_DATE

while current <= END_DATE:
    day = current.date()

    ad_info = _active_safe(antara_source, day)
    pd_info = _active_safe(pd_source, day)

    md_planet = CURRENT_MD
    ad_planet = ad_info["planet"] if ad_info else CURRENT_AD
    pd_planet = pd_info["planet"] if pd_info else None

    md_houses, md_score = _planet_score_safe(md_planet)
    ad_houses, ad_score = _planet_score_safe(ad_planet)
    pd_houses, pd_score = _planet_score_safe(pd_planet)

    total_score = md_score * 1 + ad_score * 2 + pd_score * 3

    active_layers = sum(x > 0 for x in (md_score, ad_score, pd_score))

    if pd_score >= 3 and active_layers >= 2 and total_score >= 12:
        level = "HIGH"
    elif pd_score > 0 and active_layers >= 2 and total_score >= 6:
        level = "MEDIUM"
    elif total_score > 0:
        level = "LOW"
    else:
        level = "NONE"

    daily_results.append({
        "date": current,
        "MD": md_planet, "AD": ad_planet, "PD": pd_planet,
        "MD_houses": md_houses, "AD_houses": ad_houses, "PD_houses": pd_houses,
        "md_score": md_score, "ad_score": ad_score, "pd_score": pd_score,
        "total_score": total_score,
        "active_layers": active_layers,
        "level": level,
    })

    current += timedelta(days=1)

print("\ndaily_results rebuilt fresh —", len(daily_results), "records.")
print("Keys present:", sorted(daily_results[0].keys()))

# ------------------------------------------------------------
# 5. RANK + TOP 20
# ------------------------------------------------------------

ranked = sorted(
    daily_results,
    key=lambda x: (x["total_score"], x["pd_score"], x["ad_score"], x["md_score"]),
    reverse=True,
)

print("\n" + "=" * 76)
print("TOP 20 DASHA DATES - FINAL SAFE RANKING")
