# ------------------------------------------------------------
# 1. CONFIG
# ------------------------------------------------------------

PROMOTION_HOUSES = {2, 6, 10, 11}

HOUSE_WEIGHT = {
    2: 1,
    6: 2,
    10: 3,
    11: 3,
}

NATAL_TARGET_MAP = {
    "Ketu": [],
    "Venus": [2],
    "Sun": [6],
    "Moon": [6],
    "Mars": [],
    "Rahu": [6],
    "Jupiter": [6],
    "Saturn": [6, 10, 11],
    "Mercury": [6, 10, 11],
}

START_DATE = datetime(2026, 7, 12)
END_DATE   = datetime(2026, 11, 27)

CURRENT_MD = "Jupiter"
CURRENT_AD = "Venus"


# ------------------------------------------------------------
# 2. SAFE DATE CONVERSION
# ------------------------------------------------------------

def _as_date_safe(x):

    if x is None:
        return None

    if isinstance(x, datetime):
        return x.date()

    if isinstance(x, date):
        return x

    if isinstance(x, str):

        text = x.strip()

        formats = (
            "%Y-%m-%d",
            "%d-%m-%Y",
            "%Y/%m/%d",
            "%d/%m/%Y",
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d %H:%M",
        )

        for fmt in formats:
            try:
                return datetime.strptime(text, fmt).date()
            except ValueError:
                pass

    if hasattr(x, "date"):
        try:
            return x.date()
        except Exception:
            pass

    return None


# ------------------------------------------------------------
# 3. UNIVERSAL DASHA ENTRY PARSER
#
# IMPORTANT:
# Actual source may contain:
# MD / AD / PD
# or planet / lord / name / dasha
# ------------------------------------------------------------

def _entry_safe(e):

    if isinstance(e, dict):

        # ----------------------------------------------------
        # Planet field
        # ----------------------------------------------------

        planet = (
            e.get("planet")
            or e.get("lord")
            or e.get("name")
            or e.get("dasha")
            or e.get("MD")
            or e.get("AD")
            or e.get("PD")
            or e.get("md")
            or e.get("ad")
            or e.get("pd")
        )

        # ----------------------------------------------------
        # Start field
        # ----------------------------------------------------

        start = (
            e.get("start")
            or e.get("start_date")
            or e.get("from")
            or e.get("begin")
            or e.get("START")
            or e.get("START_DATE")
            or e.get("FROM")
        )

        # ----------------------------------------------------
        # End field
        # ----------------------------------------------------

        end = (
            e.get("end")
            or e.get("end_date")
            or e.get("to")
            or e.get("finish")
            or e.get("END")
            or e.get("END_DATE")
            or e.get("TO")
        )

        return {
            "planet": planet,
            "start": _as_date_safe(start),
            "end": _as_date_safe(end),
        }

    # --------------------------------------------------------
    # Tuple / list format
    # --------------------------------------------------------

    if isinstance(e, (list, tuple)) and len(e) >= 3:

        return {
            "planet": e[0],
            "start": _as_date_safe(e[1]),
            "end": _as_date_safe(e[2]),
        }

    return {
        "planet": None,
        "start": None,
        "end": None,
    }


# ------------------------------------------------------------
# 4. SPECIAL PARSER FOR MD / AD / PD RECORDS
#
# Handles records such as:
#
# MD=Sun | AD=Moon | PD=Mercury | start -> end
# ------------------------------------------------------------

def _layer_entry_safe(e, layer):

    if not isinstance(e, dict):
        return _entry_safe(e)

    layer_upper = layer.upper()
    layer_lower = layer.lower()

    planet = (
        e.get(layer_upper)
        or e.get(layer_lower)
        or e.get("planet")
        or e.get("lord")
        or e.get("name")
        or e.get("dasha")
    )

    start = (
        e.get("start")
        or e.get("start_date")
        or e.get("from")
        or e.get("begin")
        or e.get("START")
        or e.get("START_DATE")
        or e.get("FROM")
    )

    end = (
        e.get("end")
        or e.get("end_date")
        or e.get("to")
        or e.get("finish")
        or e.get("END")
        or e.get("END_DATE")
        or e.get("TO")
    )

    return {
        "planet": planet,
        "start": _as_date_safe(start),
        "end": _as_date_safe(end),
    }


# ------------------------------------------------------------
# 5. ACTIVE DASHA FINDER
# ------------------------------------------------------------

def _active_layer_safe(entries, day, layer):

    for raw in entries or []:

        e = _layer_entry_safe(raw, layer)

        if (
            e["planet"]
            and e["start"]
            and e["end"]
            and e["start"] <= day <= e["end"]
        ):
            return e

    return None


# ------------------------------------------------------------
# 6. PLANET SCORE
# ------------------------------------------------------------

def _planet_score_safe(planet):

    if not planet:
        return [], 0

    houses = sorted(
        set(
            NATAL_TARGET_MAP.get(
                planet,
                []
            )
        ).intersection(PROMOTION_HOUSES)
    )

    score = sum(
        HOUSE_WEIGHT[h]
        for h in houses
    )

    return houses, score


