# ============================================================
# FIX — KP NAKSHATRA BOUNDARY INDEX
# ============================================================

NAKSHATRA_SIZE = 360.0 / 27.0
PADA_SIZE = NAKSHATRA_SIZE / 4.0

nakshatra_lords = [
    "Ketu",
    "Venus",
    "Sun",
    "Moon",
    "Mars",
    "Rahu",
    "Jupiter",
    "Saturn",
    "Mercury",
    "Ketu",
    "Venus",
    "Sun",
    "Moon",
    "Mars",
    "Rahu",
    "Jupiter",
    "Saturn",
    "Mercury",
    "Ketu",
    "Venus",
    "Sun",
    "Moon",
    "Mars",
    "Rahu",
    "Jupiter",
    "Saturn",
    "Mercury"
]

def get_star_info(longitude):

    # Always force longitude into [0, 360)
    longitude = float(longitude) % 360.0

    nak_index = int(longitude / NAKSHATRA_SIZE)

    # Safety clamp: valid indexes are 0–26
    nak_index = max(0, min(nak_index, 26))

    nak_start = nak_index * NAKSHATRA_SIZE

    within_nak = longitude - nak_start

    # Safety clamp
    within_nak = max(
        0.0,
        min(within_nak, NAKSHATRA_SIZE - 1e-12)
    )

    star_lord = nakshatra_lords[nak_index]

    pada = int(within_nak / PADA_SIZE) + 1

    # Safety clamp: Pada must be 1–4
    pada = max(1, min(pada, 4))

    return (
        nak_index + 1,
        star_lord,
        pada,
        within_nak
    )

print("KP Nakshatra boundary fix loaded successfully.")

