print("=" * 72)

monthly_factor = {7: 1.0, 8: 1.05, 9: 1.1, 10: 1.2, 11: 1.15}
monthly_scores = {}
current = START_DATE

while current <= END_DATE:
    next_month = date(current.year + (1 if current.month == 12 else 0), (current.month % 12) + 1, 1)
    month_end = min(next_month - timedelta(days=1), END_DATE)
    factor = monthly_factor.get(current.month, 1.0)
    score = total_score * factor
    month_name = current.strftime("%B %Y")
    monthly_scores[month_name] = score
    print(f"{month_name:15s} | {current.strftime('%d-%m-%Y')} → {month_end.strftime('%d-%m-%Y')} | Score: {score:.2f}")
    current = next_month

best_month = max(monthly_scores, key=monthly_scores.get)
print("\nSTRONGEST WINDOW:", best_month, "(Score:", round(monthly_scores[best_month], 2), ")")

