CAREER_HOUSES_D4 = {2, 6, 10, 11}

def _house_match(value):

    if value is None:
        return False

    if isinstance(value, (list, tuple, set)):
        try:
            return bool(CAREER_HOUSES_D4.intersection(
                set(int(v) for v in value)
            ))
        except:
            return False

    return False


def _d4_final_score(r):

    base = float(r.get("_score", 0))

    level = str(r.get("level", "")).upper()

    # HIGH-level confirmation
    high_bonus = 3.0 if level == "HIGH" else 0.0

    # PD-active confirmation
    pd_bonus = 2.0 if r.get("PD") not in (None, "", "None") else 0.0

    # Career-house linkage
    career_bonus = 0.0

    if _house_match(r.get("MD_houses")):
        career_bonus += 1.0

    if _house_match(r.get("AD_houses")):
        career_bonus += 1.0

    if _house_match(r.get("PD_houses")):
        career_bonus += 2.0

    return base + high_bonus + pd_bonus + career_bonus


