def _d4_date(x):
    if isinstance(x, datetime):
        return x.date()
    if isinstance(x, date):
        return x

    if isinstance(x, str):
        for fmt in (
            "%Y-%m-%d",
            "%d-%m-%Y",
            "%Y-%m-%d %H:%M:%S",
            "%d-%m-%Y %H:%M:%S"
        ):
            try:
                return datetime.strptime(x, fmt).date()
            except:
                pass

    raise ValueError(f"Unsupported date value: {x}")


