from datetime import date, datetime

print("\n" + "=" * 76)
print("STEP 18N-D4.1-FINAL — PROMOTION DATE TIE-BREAKER")
print("=" * 76)

# ------------------------------------------------
# 1. SAFETY CHECK
# ------------------------------------------------

if "d4_ranked" not in globals():
    raise RuntimeError(
        "d4_ranked not found. Run STEP 18N-D4-FINAL first."
    )

if not d4_ranked:
    raise RuntimeError("D4 ranking is empty.")

print("D4 ranked records :", len(d4_ranked))


# ------------------------------------------------
# 2. SAFE VALUE HELPERS
# ------------------------------------------------

def _safe_text(x):
    if x is None:
        return ""
    return str(x).strip().lower()


def _safe_date(x):

    if isinstance(x, datetime):
        return x.date()

    if isinstance(x, date):
        return x

    if isinstance(x, str):

        for fmt in (
            "%Y-%m-%d",
            "%d-%m-%Y",
            "%Y-%m-%d %H:%M:%S",
            "%d-%m-%Y %H:%M:%S"
        ):
            try:
                return datetime.strptime(x, fmt).date()
            except:
                pass

    return None


# ------------------------------------------------
# 3. IDENTIFY D4 TOP-SCORE GROUP
# ------------------------------------------------

max_d4_score = max(
    float(r.get("d4_score", 0))
    for r in d4_ranked
)

top_candidates = [
    r for r in d4_ranked
    if float(r.get("d4_score", 0)) == max_d4_score
]

print("Maximum D4 score :", max_d4_score)
print("Top-score dates  :", len(top_candidates))


# ------------------------------------------------
# 4. TIE-BREAKER SCORING
#
# Priority:
#   1. D3 score
#   2. HIGH level
#   3. PD active
#   4. PD houses 2/6/10/11
#   5. AD houses 2/6/10/11
#   6. MD houses 2/6/10/11
# ------------------------------------------------

CAREER_HOUSES = {2, 6, 10, 11}


def _house_strength(value):

    if not isinstance(value, (list, tuple, set)):
        return 0

    try:
        houses = set(int(v) for v in value)
    except:
        return 0

    return len(houses.intersection(CAREER_HOUSES))


def _tie_score(r):

    score = 0.0

    # D3 base strength
    score += float(r.get("_score", 0)) * 0.10

    # HIGH confirmation
    if _safe_text(r.get("level")) == "high":
        score += 5.0

    # PD active
    if _safe_text(r.get("PD")) not in ("", "none"):
        score += 4.0

    # Career-house hierarchy
    score += _house_strength(r.get("PD_houses")) * 3.0
    score += _house_strength(r.get("AD_houses")) * 2.0
    score += _house_strength(r.get("MD_houses")) * 1.0

    return round(score, 4)


for r in top_candidates:
    r["d41_tie_score"] = _tie_score(r)


# ------------------------------------------------
# 5. FINAL SORT
# ------------------------------------------------

final_candidates = sorted(
    top_candidates,
    key=lambda r: (
        -float(r.get("d41_tie_score", 0)),
        -float(r.get("_score", 0)),
        _safe_date(r.get("_date")) or date.max
    )
)


# ------------------------------------------------
# 6. SHOW ALL TIED DATES
# ------------------------------------------------

print("\n" + "=" * 76)
print("D4 TOP-SCORE TIE GROUP")
print("=" * 76)

for i, r in enumerate(final_candidates, start=1):

    d = _safe_date(r.get("_date"))

    print(
        f"{i:02d}. "
        f"DATE={d.strftime('%d-%m-%Y') if d else 'N/A'} | "
        f"MD={r.get('MD')} | "
        f"AD={r.get('AD')} | "
        f"PD={r.get('PD')} | "
        f"D3={r.get('_score')} | "
        f"D4={r.get('d4_score')} | "
        f"TIE={r.get('d41_tie_score')} | "
        f"LEVEL={r.get('level')}"
    )


# ------------------------------------------------
# 7. FINAL WINNER
# ------------------------------------------------

final_winner = final_candidates[0]

winner_date = _safe_date(final_winner.get("_date"))


