# ------------------------------------------------
# 1. CHECK REQUIRED DATA
# ------------------------------------------------

if "final_candidates" not in globals():
    raise RuntimeError(
        "final_candidates not found. Run D4.2 / D4 DEBUG first."
    )

if not final_candidates:
    raise RuntimeError("final_candidates is empty.")

print("Total final candidates :", len(final_candidates))

# ------------------------------------------------
# 2. KP CAREER HOUSES
# ------------------------------------------------

CAREER_HOUSES = {2, 6, 10, 11}
NEGATIVE_HOUSES = {5, 8, 12}

# ------------------------------------------------
# 3. HOUSE SCORE FUNCTION
# ------------------------------------------------

def kp_house_score(houses):
    houses = set(houses or [])

    positive = len(houses & CAREER_HOUSES)
    negative = len(houses & NEGATIVE_HOUSES)

    return (positive * 2) - (negative * 1)


# ------------------------------------------------
# 4. VALIDATE EACH CANDIDATE
# ------------------------------------------------

validated = []

for r in final_candidates:

    md_houses = set(r.get("MD_houses", []) or [])
    ad_houses = set(r.get("AD_houses", []) or [])
    pd_houses = set(r.get("PD_houses", []) or [])

    md_score = kp_house_score(md_houses)
    ad_score = kp_house_score(ad_houses)
    pd_score = kp_house_score(pd_houses)

    structural_score = (
        md_score +
        ad_score +
        pd_score
    )

    positive_links = (
        len(md_houses & CAREER_HOUSES) +
        len(ad_houses & CAREER_HOUSES) +
        len(pd_houses & CAREER_HOUSES)
    )

    negative_links = (
        len(md_houses & NEGATIVE_HOUSES) +
        len(ad_houses & NEGATIVE_HOUSES) +
        len(pd_houses & NEGATIVE_HOUSES)
    )

    x = dict(r)

    x["structural_score"] = structural_score
    x["positive_links"] = positive_links
    x["negative_links"] = negative_links

    validated.append(x)


# ------------------------------------------------
# 5. FIND STRONGEST STRUCTURAL CANDIDATES
# ------------------------------------------------

max_structural = max(
    x["structural_score"] for x in validated
)

strongest = [
    x for x in validated
    if x["structural_score"] == max_structural
]

