print("-" * 76)

for x in strongest[:20]:

    d = x.get("date")

    print(
        f"DATE={d.strftime('%d-%m-%Y') if hasattr(d, 'strftime') else d} | "
        f"MD={x.get('MD')} | "
        f"AD={x.get('AD')} | "
        f"PD={x.get('PD')} | "
        f"POS={x['positive_links']} | "
        f"NEG={x['negative_links']} | "
        f"STRUCT={x['structural_score']} | "
        f"D3={x.get('total_score', 0)}"
    )


