print("=" * 76)

# ------------------------------------------------
# 1. REQUIRED DATA CHECK
# ------------------------------------------------

if "validated" not in globals():
    raise RuntimeError(
        "validated data not found. Run STEP 18N-D4.3 first."
    )

if not validated:
    raise RuntimeError("validated is empty.")

# ------------------------------------------------
# 2. OCTOBER CANDIDATES
# ------------------------------------------------

october = [
    x for x in validated
    if hasattr(x.get("date"), "year")
    and x["date"].year == 2026
    and x["date"].month == 10
]

print("October candidates :", len(october))

if not october:
    raise RuntimeError("No October 2026 candidates found.")


# ------------------------------------------------
# 3. COMPARE ALL AVAILABLE KEYS
# ------------------------------------------------

print("\n" + "-" * 76)
print("FIELD-BY-FIELD VARIATION CHECK")
print("-" * 76)

keys = sorted(set().union(*(x.keys() for x in october)))

variable_fields = []
identical_fields = []

for key in keys:

    values = []

    for x in october:
        value = x.get(key)

        # datetime/date values are normalized
        if hasattr(value, "strftime"):
            value = value.strftime("%Y-%m-%d")

        # lists -> tuple for comparison
        if isinstance(value, list):
            value = tuple(value)

        values.append(repr(value))

    unique_values = set(values)

    if len(unique_values) > 1:
        variable_fields.append(key)
    else:
        identical_fields.append(key)


print("VARIABLE FIELDS")
for key in variable_fields:
    print("  *", key)

print("\nIDENTICAL FIELDS")
for key in identical_fields:
    print("  =", key)


# ------------------------------------------------
# 4. SHOW ACTUAL DIFFERENCES
# ------------------------------------------------

print("\n" + "-" * 76)
print("ACTUAL OCTOBER DIFFERENCES")
print("-" * 76)

if variable_fields:

    for key in variable_fields:

        print("\nFIELD :", key)

        seen = []

        for x in october:

            value = x.get(key)

            if hasattr(value, "strftime"):
                value = value.strftime("%Y-%m-%d")

            if isinstance(value, list):
                value = tuple(value)

            if value not in seen:
                seen.append(value)

                print("  VALUE :", value)

else:

    print("NO VARIABLE FIELDS FOUND.")


# ------------------------------------------------
# 5. DATE-LEVEL SIGNATURE
# ------------------------------------------------

print("\n" + "-" * 76)
print("DATE-LEVEL SIGNATURE CHECK")
print("-" * 76)

signatures = {}

for x in october:

    d = x["date"]

    signature = tuple(
        repr(x.get(k))
        for k in sorted(x.keys())
        if k != "date"
    )

    signatures.setdefault(signature, []).append(d)


print("Unique non-date signatures :", len(signatures))

for i, (signature, dates) in enumerate(signatures.items(), 1):

    print(
        f"Signature {i}: {len(dates)} date(s)"
    )

    print(
        "Dates:",
        ", ".join(
            d.strftime("%d-%m-%Y")
            if hasattr(d, "strftime")
            else str(d)
            for d in dates
        )
    )


