def freeze_value(v):
    if isinstance(v, dict):
        return tuple(sorted(
            (str(k), freeze_value(val))
            for k, val in v.items()
        ))
    if isinstance(v, (list, tuple)):
        return tuple(freeze_value(x) for x in v)
    if isinstance(v, set):
        return tuple(sorted(freeze_value(x) for x in v))
    return v

def non_date_signature(record):
    return tuple(
        (k, freeze_value(v))
        for k, v in sorted(record.items())
        if k not in ("date", "_date")
    )

