# ------------------------------------------------------------
# 5. KP SUB-LORD CALCULATOR
# ------------------------------------------------------------

def kp_sub_lord(longitude):
    """
    Calculate KP sub-lord from sidereal longitude.
    """

    longitude = float(longitude) % 360.0

    nak_index = int(longitude / NAKSHATRA_SIZE)

    # Fix: Ensure index is within 0-26 range
    if nak_index > 26:
        nak_index = 26
    if nak_index < 0:
        nak_index = 0

    nak_start = nak_index * NAKSHATRA_SIZE
    within_nak = longitude - nak_start

    nak_lord = NAK_LORDS[nak_index]

    # Starting planet = Nakshatra lord
    start_index = DASHA_SEQUENCE.index(nak_lord)

    # Convert Nakshatra fraction into Vimshottari years
    elapsed_years = (
        within_nak / NAKSHATRA_SIZE
    ) * SUB_TOTAL

    cumulative = 0.0
    sub_lord = None

    for i in range(9):
        planet = DASHA_SEQUENCE[(start_index + i) % 9]
        portion = (DASHA_YEARS[planet] / SUB_TOTAL) * SUB_TOTAL
        next_cumulative = cumulative + portion

        if elapsed_years < next_cumulative:
            sub_lord = planet
            break

        cumulative = next_cumulative

    if sub_lord is None:
        sub_lord = DASHA_SEQUENCE[(start_index + 8) % 9]

    pada = int(within_nak / (NAKSHATRA_SIZE / 4.0)) + 1
    pada = max(1, min(pada, 4))

    sign_index = int(longitude / 30.0)
    sign_index = max(0, min(sign_index, 11))

    return {
        "sign": SIGN_NAMES[sign_index],
        "sign_lord": SIGN_LORDS[sign_index],
        "nakshatra": NAKSHATRA_NAMES[nak_index],
        "nakshatra_index": nak_index + 1,
        "star_lord": nak_lord,
        "sub_lord": sub_lord,
        "pada": pada,
        "longitude": longitude,
    }

# ------------------------------------------------------------
# 6. SWISS EPHEMERIS SETTINGS
# ------------------------------------------------------------

swe.set_sid_mode(swe.SIDM_LAHIRI)

PLANET_MAP = {
    "Sun": swe.SUN,
    "Moon": swe.MOON,
    "Mars": swe.MARS,
    "Mercury": swe.MERCURY,
    "Jupiter": swe.JUPITER,
    "Venus": swe.VENUS,
    "Saturn": swe.SATURN,
}

NODE_MODE = "MEAN"

# ------------------------------------------------------------
# 7. JULIAN DAY
# ------------------------------------------------------------

def jd_from_datetime(dt):
    return swe.julday(
        dt.year,
        dt.month,
        dt.day,
        dt.hour
        + dt.minute / 60.0
        + dt.second / 3600.0
    )

# ------------------------------------------------------------
# 8. SINGLE DATE TRANSIT BUILDER
# ------------------------------------------------------------

def build_transit_record(dt):
    jd = jd_from_datetime(dt)
    result = {
        "date": dt,
        "jd": jd,
        "node_mode": NODE_MODE,
        "planets": {},
    }
    flags = swe.FLG_SWIEPH | swe.FLG_SIDEREAL

    for name, planet_id in PLANET_MAP.items():
        xx, retflag = swe.calc_ut(jd, planet_id, flags)
        longitude = float(xx[0]) % 360.0
        kp = kp_sub_lord(longitude)
        result["planets"][name] = {
            "longitude": longitude,
            "sign": kp["sign"],
            "sign_lord": kp["sign_lord"],
            "nakshatra": kp["nakshatra"],
            "nakshatra_index": kp["nakshatra_index"],
            "star_lord": kp["star_lord"],
            "sub_lord": kp["sub_lord"],
            "pada": kp["pada"],
        }

    node_flags = swe.FLG_SWIEPH | swe.FLG_SIDEREAL
    xx, retflag = swe.calc_ut(jd, swe.MEAN_NODE, node_flags)
    rahu_longitude = float(xx[0]) % 360.0
    ketu_longitude = (rahu_longitude + 180.0) % 360.0

    rahu_kp = kp_sub_lord(rahu_longitude)
    ketu_kp = kp_sub_lord(ketu_longitude)

    result["planets"]["Rahu"] = {
        "longitude": rahu_longitude,
        "sign": rahu_kp["sign"],
        "sign_lord": rahu_kp["sign_lord"],
        "nakshatra": rahu_kp["nakshatra"],
        "nakshatra_index": rahu_kp["nakshatra_index"],
        "star_lord": rahu_kp["star_lord"],
        "sub_lord": rahu_kp["sub_lord"],
        "pada": rahu_kp["pada"],
    }

    result["planets"]["Ketu"] = {
        "longitude": ketu_longitude,
        "sign": ketu_kp["sign"],
        "sign_lord": ketu_kp["sign_lord"],
        "nakshatra": ketu_kp["nakshatra"],
        "nakshatra_index": ketu_kp["nakshatra_index"],
        "star_lord": ketu_kp["star_lord"],
        "sub_lord": ketu_kp["sub_lord"],
        "pada": ketu_kp["pada"],
    }
    return result

