def unwrap_transit_record(obj):
    """
    Accept common structures:
      date -> dict
      date -> object
      list of records
    """
    if isinstance(obj, dict):
        return obj

    if isinstance(obj, list):
        if len(obj) == 0:
            return {}
        if isinstance(obj[0], dict):
            return obj[0]

    return {}


