def get_transit_houses(record):

    houses = set()

    if not isinstance(record, dict):
        return houses

    # Direct house fields
    for key in [
        "house",
        "houses",
        "target_house",
        "target_houses",
        "transit_house",
        "transit_houses"
    ]:

        value = record.get(key)

        if isinstance(value, int):
            houses.add(value)

        elif isinstance(value, (list, tuple, set)):
            for x in value:
                if isinstance(x, int):
                    houses.add(x)

    return houses


def get_transit_planet_names(record):

    names = set()

    if not isinstance(record, dict):
        return names

    for key in [
        "planet",
        "planets",
        "transit_planet",
        "transit_planets"
    ]:

        value = record.get(key)

        if isinstance(value, str):
            names.add(value)

        elif isinstance(value, (list, tuple, set)):
            for x in value:
                if isinstance(x, str):
                    names.add(x)

        elif isinstance(value, dict):
            names.update(str(k) for k in value.keys())

    return names


# ------------------------------------------------
# 7. TRUE TRANSIT DISCRIMINATION
# ------------------------------------------------

transit_discriminated = []

for item in candidates:

    row = item

    if isinstance(item, dict) and "row" in item:
        row = item["row"]

    if not isinstance(row, dict):
        continue

    dt = row.get("date")

    if dt is None:
        continue

    # Find matching transit record
    record = None

    if dt in transit_planets:
        record = transit_planets[dt]

    else:
        try:
            target_date = dt.date()

            for tk, tv in transit_planets.items():
                try:
                    if hasattr(tk, "date") and tk.date() == target_date:
                        record = tv
                        break
                except Exception:
                    pass

        except Exception:
            pass

    if record is None:
        continue

    record = unwrap_transit_record(record)

    transit_houses = get_transit_houses(record)
    transit_names = get_transit_planet_names(record)

    promotion_hit = bool(
        transit_houses.intersection(PROMOTION_HOUSES)
    )

    if promotion_hit:

        transit_discriminated.append({
            "candidate": item,
            "date": dt,
            "transit_houses": sorted(transit_houses),
            "transit_planets": sorted(transit_names),
            "promotion_hit": True
        })


