# ------------------------------------------------
# 1. DATE NORMALIZER
# ------------------------------------------------

def normalize_date_key(x):

    if x is None:
        return None

    # datetime / date
    if hasattr(x, "date") and not isinstance(x, str):
        try:
            return x.date().isoformat()
        except Exception:
            pass

    if hasattr(x, "isoformat") and not isinstance(x, str):
        try:
            return x.isoformat()[:10]
        except Exception:
            pass

    # string
    if isinstance(x, str):
        s = x.strip()

        # YYYY-MM-DD
        if len(s) >= 10:
            return s[:10]

        return s

    return str(x)


