# ------------------------------------------------
# 2. SAFE VALUE CONVERTER
# ------------------------------------------------

def as_set(value):

    if value is None:
        return set()

    if isinstance(value, (set, list, tuple)):
        return set(value)

    return {value}


# ------------------------------------------------
# 3. GET CANDIDATE ROW
# ------------------------------------------------

def get_candidate_row(item):

    if isinstance(item, dict) and "row" in item:
        return item["row"]

    return item


# ------------------------------------------------
# 4. EXTRACT MD / AD / PD
# ------------------------------------------------

def get_dasha_lords(row):

    if not isinstance(row, dict):
        return set()

    lords = set()

    for key in ["MD", "AD", "PD"]:

        value = row.get(key)

        if isinstance(value, str):
            lords.add(value.strip())

    return lords


# ------------------------------------------------
# 5. EXTRACT DASHA HOUSES
# ------------------------------------------------

def get_dasha_houses(row):

    if not isinstance(row, dict):
        return set()

    houses = set()

    for key in [
        "MD_houses",
        "AD_houses",
        "PD_houses"
    ]:

        value = row.get(key)

        if isinstance(value, (list, tuple, set)):
            for h in value:
                try:
                    houses.add(int(h))
                except Exception:
                    pass

        elif isinstance(value, int):
            houses.add(value)

    return houses


# ------------------------------------------------
# 6. FIND PLANET DICTIONARY
# ------------------------------------------------

def get_planet_dict(transit):

    if not isinstance(transit, dict):
        return {}

    planets = transit.get("planets")

    if isinstance(planets, dict):
        return planets

    return {}


# ------------------------------------------------
# 7. EXTRACT TRANSIT LORDS
# ------------------------------------------------

def extract_transit_lords(pdata):

    result = {
        "star": None,
        "sub": None,
        "sign": None
    }

    if not isinstance(pdata, dict):
        return result

    # possible field names
    star_keys = [
        "star",
        "star_lord",
        "nakshatra_lord",
        "STAR",
        "STAR_LORD"
    ]

    sub_keys = [
        "sub",
        "sub_lord",
        "sublord",
        "SUB",
        "SUB_LORD"
    ]

    sign_keys = [
        "sign",
        "rashi",
        "zodiac"
    ]

    for key in star_keys:
        if key in pdata:
            result["star"] = pdata[key]
            break

    for key in sub_keys:
        if key in pdata:
            result["sub"] = pdata[key]
            break

    for key in sign_keys:
        if key in pdata:
            result["sign"] = pdata[key]
            break

    # Nested / alternate formats
    if result["star"] is None:
        for key, value in pdata.items():
            k = str(key).lower()
            if "star" in k:
                result["star"] = value
                break

    if result["sub"] is None:
        for key, value in pdata.items():
            k = str(key).lower()
            if "sub" in k:
                result["sub"] = value
                break

    return result


# ------------------------------------------------
# 8. EXISTING NATAL PLANET-HOUSE MAPS
# ------------------------------------------------

# We DO NOT invent a natal house map.
# Use one only if already present in notebook.

existing_house_maps = []

for name, obj in list(globals().items()):

    if not isinstance(obj, dict):
        continue

    lname = name.lower()

    if (
        "planet" in lname
        and "house" in lname
    ):
        existing_house_maps.append((name, obj))

    elif lname in [
        "planet_houses",
        "planet_house",
        "planet_house_map",
        "natal_planet_houses"
    ]:
        existing_house_maps.append((name, obj))


print("\nExisting planet-house maps found :",
      [x[0] for x in existing_house_maps])


# ------------------------------------------------
# 9. BUILD PLANET -> HOUSE LOOKUP
# ------------------------------------------------

planet_house_lookup = {}

for name, mapping in existing_house_maps:

    for planet, houses in mapping.items():

        if isinstance(planet, str):

            if isinstance(houses, (list, tuple, set)):
                for h in houses:
                    try:
                        planet_house_lookup.setdefault(
                            planet, set()
                        ).add(int(h))
                    except Exception:
                        pass

            elif isinstance(houses, int):

                planet_house_lookup.setdefault(
                    planet, set()
                ).add(houses)


# ------------------------------------------------
# 10. TRUE KP TRANSIT TEST
# ------------------------------------------------

transit_results = []

for pair in transit_candidate_pairs:

    date = pair.get("date")
    candidate = pair.get("candidate")
    transit = pair.get("transit")

    row = get_candidate_row(candidate)

    if not isinstance(row, dict):
        continue

    dasha_lords = get_dasha_lords(row)
    dasha_houses = get_dasha_houses(row)

    planets = get_planet_dict(transit)

    star_hits = []
    sub_hits = []
    house_hits = []
    planet_hits = []

    # --------------------------------------------
    # Examine every transit planet
    # --------------------------------------------

    for planet_name, pdata in planets.items():

        info = extract_transit_lords(pdata)

        star = info["star"]
        sub = info["sub"]

        # Transit STAR lord matches MD/AD/PD
        if isinstance(star, str):

            if star.strip() in dasha_lords:
                star_hits.append(
                    (planet_name, star.strip())
                )

        # Transit SUB lord matches MD/AD/PD
        if isinstance(sub, str):

            if sub.strip() in dasha_lords:
                sub_hits.append(
                    (planet_name, sub.strip())
                )

        # If natal planet-house map exists,
        # test transit planet's own natal houses.
        if planet_name in planet_house_lookup:

            phouses = planet_house_lookup[planet_name]

            if phouses.intersection(PROMOTION_HOUSES):

                house_hits.append(
                    (
                        planet_name,
                        sorted(
                            phouses.intersection(
                                PROMOTION_HOUSES
                            )
                        )
                    )
                )

                planet_hits.append(planet_name)

    # --------------------------------------------
    # Dasha houses themselves
    # --------------------------------------------

    dasha_promotion_hit = bool(
        dasha_houses.intersection(
            PROMOTION_HOUSES
        )
    )

    # --------------------------------------------
    # KP scoring
    # --------------------------------------------

    score = 0

    # Transit star -> MD/AD/PD
    score += len(star_hits) * 2

    # Transit sub -> MD/AD/PD
    score += len(sub_hits) * 3

    # Natal planet -> promotion houses
    score += len(house_hits) * 2

    # Candidate dasha houses contain
    # promotion houses
    if dasha_promotion_hit:
        score += 2

    # Strongest condition:
    # sub + star connection together
    if star_hits and sub_hits:
        score += 3

    # --------------------------------------------
    # Save result
    # --------------------------------------------

    transit_results.append({
        "date": date,
        "candidate": candidate,
        "score": score,
        "star_hits": star_hits,
        "sub_hits": sub_hits,
        "house_hits": house_hits,
        "dasha_houses": sorted(dasha_houses),
        "dasha_promotion_hit": dasha_promotion_hit
    })


# ------------------------------------------------
# 11. SORT WITHOUT DESTROYING ORIGINAL CANDIDATES
# ------------------------------------------------

transit_results_sorted = sorted(
    transit_results,
    key=lambda x: (
        x["score"],
        len(x["sub_hits"]),
        len(x["star_hits"])
    ),
    reverse=True
)


