from datetime import datetime, date

print("=" * 76)
print("STEP 18N-D5.13 - HISTORICAL EVENT MAPPING")
print("=" * 76)

# ------------------------------------------------
# 1. SAFETY
# ------------------------------------------------

if "candidates" not in globals():
    raise RuntimeError("candidates not found")

if "event_results" not in globals():
    raise RuntimeError("event_results not found")

print("Candidates :", len(candidates))
print("Available event keys :", list(event_results.keys()))


# ------------------------------------------------
# 2. CONFIRMED HISTORICAL EVENTS
# ------------------------------------------------

HISTORICAL_EVENTS = {
    "Marriage": date(2013, 3, 13),
    "Childbirth": date(2014, 7, 1),
    "Major job-change": date(2018, 4, 20),
}


# ------------------------------------------------
# 3. IMPORTANT:
#    DO NOT ASSUME CHILD/JOB = SAME EVENT KEY
# ------------------------------------------------

EVENT_SOURCE_MAP = {
    "Marriage": "Marriage",

    # Childbirth and job-change are calibration events.
    # Their validation will be performed through the
    # candidate's historical KP structure, not by falsely
    # treating them as 2026 promotion-event keys.

    "Childbirth": None,
    "Major job-change": None,
}


# ------------------------------------------------
# 4. SAFE DATE
# ------------------------------------------------

def _to_date(x):

    if isinstance(x, datetime):
        return x.date()

    if isinstance(x, date):
        return x

    if isinstance(x, str):

        for fmt in (
            "%Y-%m-%d",
            "%d-%m-%Y",
            "%Y-%m-%d %H:%M:%S",
            "%d-%m-%Y %H:%M:%S",
        ):
            try:
                return datetime.strptime(x, fmt).date()
            except Exception:
                pass

    return None


# ------------------------------------------------
# 5. MAP AVAILABLE RESULTS
# ------------------------------------------------

D513_RESULTS = {
    "events": HISTORICAL_EVENTS,
    "event_source_map": EVENT_SOURCE_MAP,
    "available_keys": list(event_results.keys()),
    "candidate_count": len(candidates),
    "matches": {},
    "scoring_applied": False,
    "elimination_applied": False,
}


# ------------------------------------------------
# 6. MARRIAGE — DIRECT AVAILABLE RESULT
# ------------------------------------------------

marriage_results = event_results.get("Marriage", [])

if not isinstance(marriage_results, list):
    marriage_results = [marriage_results]

marriage_date = HISTORICAL_EVENTS["Marriage"]

marriage_matches = []

for item in marriage_results:

    if not isinstance(item, dict):
        continue

    start = _to_date(item.get("start"))
    end = _to_date(item.get("end"))

    if start and end and start <= marriage_date <= end:
        marriage_matches.append(item)

D513_RESULTS["matches"]["Marriage"] = marriage_matches


# ------------------------------------------------
# 7. CHILD + JOB
#    PRESERVE AS CALIBRATION EVENTS
# ------------------------------------------------

D513_RESULTS["matches"]["Childbirth"] = {
    "date": HISTORICAL_EVENTS["Childbirth"],
    "source": "historical candidate validation",
    "direct_event_result": False,
}

D513_RESULTS["matches"]["Major job-change"] = {
    "date": HISTORICAL_EVENTS["Major job-change"],
    "source": "historical candidate validation",
    "direct_event_result": False,
}


# ------------------------------------------------
# 8. OUTPUT
# ------------------------------------------------

print("\n" + "=" * 76)
print("D5.13 HISTORICAL MAPPING")
print("=" * 76)

print(
    "Marriage       :",
    len(marriage_matches),
    "direct timing match(es)"
)

print(
    "Childbirth     :",
    "CALIBRATION EVENT"
)

print(
    "Major job-change:",
    "CALIBRATION EVENT"
)

print("\nHistorical dates:")
