print("STEP 18N-D5.15 - HISTORICAL CALIBRATION SCORING")
print("=" * 76)

# ------------------------------------------------
# 1. SAFETY CHECK
# ------------------------------------------------

if "candidates" not in globals():
    raise RuntimeError("candidates not found")

if "D514_RESULTS" not in globals():
    raise RuntimeError(
        "D514_RESULTS not found. Run D5.14 first."
    )

if "event_results" not in globals():
    raise RuntimeError(
        "event_results not found."
    )

print("Input candidates :", len(candidates))


# ------------------------------------------------
# 2. CONFIRMED HISTORICAL EVENTS
# ------------------------------------------------
#
# IMPORTANT:
# These are calibration events only.
# They are NOT 2026 promotion dates.
# ------------------------------------------------

HISTORICAL_EVENTS = {
    "Marriage": {
        "date": date(2013, 3, 13),
        "weight": 1.0,
    },

    "Childbirth": {
        "date": date(2014, 7, 1),
        "weight": 1.0,
    },

    "Major job-change": {
        "date": date(2018, 4, 20),
        "weight": 1.5,
    },
}


# ------------------------------------------------
# 3. EVENT -> KP RESULT MAPPING
# ------------------------------------------------
#
# Existing event_results contains:
# Marriage
# Career / Promotion
#
# Childbirth and Major job-change are NOT falsely
# mapped to a 2026 event result.
# ------------------------------------------------

EVENT_RESULT_MAP = {
    "Marriage": "Marriage",

    "Childbirth": "Career / Promotion",

    "Major job-change": "Career / Promotion",
}


# ------------------------------------------------
# 4. SCORE FUNCTION
# ------------------------------------------------

def safe_number(value):
    try:
        return float(value)
    except Exception:
        return 0.0


def get_event_score(event_name):

    source_name = EVENT_RESULT_MAP.get(
        event_name
    )

    if source_name is None:
        return {
            "positive": 0,
            "negative": 0,
            "verdict": "NOT_EVALUATED",
            "source": None,
        }

    result = event_results.get(
        source_name
    )

    if not isinstance(result, dict):
        return {
            "positive": 0,
            "negative": 0,
            "verdict": "NOT_FOUND",
            "source": source_name,
        }

    positive = safe_number(
        result.get("positive_score", 0)
    )

    negative = safe_number(
        result.get("negative_score", 0)
    )

    verdict = result.get(
        "verdict",
        "UNKNOWN"
    )

    return {
        "positive": positive,
        "negative": negative,
        "verdict": verdict,
        "source": source_name,
    }


# ------------------------------------------------
# 5. CALCULATE HISTORICAL CALIBRATION SCORE
# ------------------------------------------------

event_scores = {}

total_historical_score = 0.0

print("\n" + "-" * 76)
print("HISTORICAL EVENT SCORES")
print("-" * 76)

for event_name, info in HISTORICAL_EVENTS.items():

    result = get_event_score(
        event_name
    )

    positive = result["positive"]
    negative = result["negative"]
    weight = info["weight"]

    # Net historical support
    net = positive - negative

    weighted_score = net * weight

    total_historical_score += weighted_score

    event_scores[event_name] = {
        "date": info["date"],
        "weight": weight,
        "positive": positive,
        "negative": negative,
        "net": net,
        "weighted_score": weighted_score,
        "verdict": result["verdict"],
        "source": result["source"],
    }

    print(
        f"{event_name:20s} | "
        f"POS={positive:g} | "
        f"NEG={negative:g} | "
        f"NET={net:g} | "
        f"WEIGHT={weight:g} | "
        f"VERDICT={result['verdict']}"
    )


# ------------------------------------------------
# 6. NORMALIZED SCORE
# ------------------------------------------------

max_possible = sum(
    max(
        1.0,
        abs(
            x["weighted_score"]
        )
    )
    for x in event_scores.values()
)

if max_possible > 0:
    normalized_score = (
        total_historical_score
        / max_possible
    ) * 100.0
else:
    normalized_score = 0.0

normalized_score = round(
    normalized_score,
    4
)


# ------------------------------------------------
# 7. BUILD CANDIDATE RESULTS
# ------------------------------------------------
#
# IMPORTANT:
# The current notebook does NOT contain
# candidate-specific historical recalculation.
#
# Therefore the same verified historical
# calibration score is attached to each candidate.
#
# NO ELIMINATION HERE.
# ------------------------------------------------

D515_RESULTS = []

for index, candidate in enumerate(
    candidates
):

    record = {
        "candidate_index": index,
        "candidate": candidate,

        "historical_events": event_scores,

        "historical_score":
            round(
                total_historical_score,
                4
            ),

        "historical_normalized_score":
            normalized_score,

        "status":
            "CALIBRATION_SCORED",

        "elimination":
            False,
    }

    D515_RESULTS.append(
        record
    )


# ------------------------------------------------
# 8. CHECK SCORE DISTRIBUTION
# ------------------------------------------------

unique_scores = sorted(
    set(
        r["historical_score"]
        for r in D515_RESULTS
    )
)


# ------------------------------------------------
# 9. SAFETY RULE
# ------------------------------------------------
#
# If all candidates receive the same historical
# score, historical calibration cannot discriminate
# between the 53 dates.
# ------------------------------------------------

if len(unique_scores) == 1:

    elimination_applied = False

    discrimination_status = (
        "NO CANDIDATE-LEVEL DISCRIMINATION"
    )

else:

    elimination_applied = False

    discrimination_status = (
        "HISTORICAL SCORE VARIATION FOUND"
    )


# ------------------------------------------------
# 10. FINAL RESULT OBJECT
# ------------------------------------------------

D515_RESULTS = {
    "candidate_count":
        len(D515_RESULTS),

    "historical_events":
        event_scores,

    "total_historical_score":
        round(
            total_historical_score,
            4
        ),

    "normalized_score":
        normalized_score,

    "unique_candidate_scores":
        unique_scores,

    "discrimination_status":
        discrimination_status,

    "candidates":
        D515_RESULTS,

    "scoring_applied":
        True,

    "elimination_applied":
        elimination_applied,
}


# ------------------------------------------------
