# ------------------------------------------------------------
# 3. READ EXISTING EVENT RESULTS
# ------------------------------------------------------------

historical_validation = {}

for event_name, event_date in HISTORICAL_EVENTS.items():

    raw = event_results.get(event_name)

    if raw is None:
        historical_validation[event_name] = {
            "date": event_date,
            "status": "NOT FOUND",
            "positive_score": 0,
            "negative_score": 0,
            "net_score": 0,
            "verdict": "NOT FOUND",
        }
        continue

    # Existing engine normally returns a dict.
    if isinstance(raw, dict):

        pos = int(
            raw.get("positive_score", 0) or 0
        )

        neg = int(
            raw.get("negative_score", 0) or 0
        )

        verdict = raw.get(
            "verdict",
            "UNKNOWN"
        )

    else:
        pos = 0
        neg = 0
        verdict = "UNKNOWN"

    historical_validation[event_name] = {
        "date": event_date,
        "status": "EVALUATED",
        "positive_score": pos,
        "negative_score": neg,
        "net_score": pos - neg,
        "verdict": verdict,
    }

