# ------------------------------------------------------------

total_positive = sum(
    x["positive_score"]
    for x in historical_validation.values()
)

total_negative = sum(
    x["negative_score"]
    for x in historical_validation.values()
)

total_net = (
    total_positive
    - total_negative
)

evaluated_events = sum(
    1
    for x in historical_validation.values()
    if x["status"] == "EVALUATED"
)

# ------------------------------------------------------------
# 6. IMPORTANT ARCHITECTURE CHECK
# ------------------------------------------------------------

candidate_dates = []

for row in final_candidates:

    value = row.get(
        "_date",
        row.get("date")
    )

    if isinstance(value, datetime):
        value = value.date()

    elif isinstance(value, str):

        parsed = None

        for fmt in (
            "%Y-%m-%d",
            "%d-%m-%Y",
            "%Y-%m-%d %H:%M:%S",
            "%d-%m-%Y %H:%M:%S",
        ):

            try:
                parsed = datetime.strptime(
                    value,
                    fmt
                ).date()
                break

            except Exception:
                pass

        value = parsed

    if isinstance(value, date):
        candidate_dates.append(value)

# ------------------------------------------------------------
