# ------------------------------------------------------------
# 1. REQUIRED INPUT CHECK
# ------------------------------------------------------------

required_objects = {
    "D519_RESULTS": globals().get("D519_RESULTS"),
    "D519_HANDOFF": globals().get("D519_HANDOFF"),
    "TRANSIT_PLANETS": globals().get("TRANSIT_PLANETS"),
    "NATAL_TARGET_MAP": globals().get("NATAL_TARGET_MAP"),
}

