# ================================================================
# ASTRO-BHUDEB — FINAL RESULT BRIDGE
# build_universal_event_v1()
#
# This was MISSING from the engine entirely (app.py's "Prediction"
# tab only ever showed hardcoded "—" placeholders because there was
# nothing here to call). It reads the D5.20 transit-discriminated
# MD/AD/PD winner via nested dict lookup and assembles the single
# Final Result dict the UI needs.
# ================================================================

def build_universal_event_v1(event_name="Career / Promotion"):
    """
    Universal Event — Final Result v1.

    Bridges D520_RANKED (transit-discriminated Dasha candidates,
    each carrying MD/AD/PD via nested dict lookup) into one
    Final-Result dict for the Streamlit Prediction tab.
    """

    def _pick(d, *keys, default=None):
        if not isinstance(d, dict):
            return default
        for k in keys:
            v = d.get(k)
            if v is not None:
                return v
        return default

    def _fmt_date(v):
        return v.strftime("%d-%m-%Y") if hasattr(v, "strftime") else (str(v) if v else "—")

    if "D520_RANKED" not in globals() or not D520_RANKED:
        return {
            "event": event_name,
            "promise": "—",
            "best_period": "—",
            "secondary": "—",
            "key_planet": "—",
            "trigger": "—",
            "main_reason": "No transit-evaluated candidates available (D520_RANKED empty).",
            "risk": "—",
            "remedy": "—",
            "confidence": "—",
        }

    winner = D520_RANKED[0]
    cand = winner.get("source_candidate", {}) or {}

    # --- nested dict lookup for MD / AD / PD (multiple key-name fallbacks,
    #     since different pipeline layers named these differently) ---
    md = _pick(cand, "MD", "mahadasha", "maha", default="—")
    ad = _pick(cand, "AD", "antardasha", "antara", default="—")
    pd_lord = _pick(cand, "PD", "pratyantardasha", "planet", default="—")

    best_period = _fmt_date(winner.get("date"))

    # secondary supporting dates (next distinct ranked dates)
    secondary_dates = []
    for row in D520_RANKED[1:8]:
        d = row.get("date")
        if d and d != winner.get("date"):
            secondary_dates.append(_fmt_date(d))
        if len(secondary_dates) >= 2:
            break
    secondary = ", ".join(secondary_dates) if secondary_dates else "—"

    total_score = winner.get("transit_score", _pick(cand, "total_score", default=0))
    core_hit_count = winner.get("core_hit_count", 0)
    core_houses = winner.get("core_houses", [])
    target_houses = winner.get("target_houses", [])

    # event houses — prefer engine's own EVENT_RULES if this event_name
    # matches, else just use whatever target houses were computed
    event_positive_houses = None
    if "EVENT_RULES" in globals() and event_name in EVENT_RULES:
        event_positive_houses = sorted(EVENT_RULES[event_name].get("positive", []))

    level = _pick(cand, "level", default=None)
    if level:
        confidence_label = level
    elif total_score >= 100:
        confidence_label = "HIGH"
    elif total_score >= 60:
        confidence_label = "MEDIUM"
    else:
        confidence_label = "LOW"

    confidence = f"{confidence_label} (score {total_score}, core-hits {core_hit_count})"

    main_reason = (
        f"MD {md} / AD {ad} / PD {pd_lord} transit-supported on {best_period}. "
        f"Core houses {core_houses} matched against "
        f"{'event houses ' + str(event_positive_houses) if event_positive_houses else 'target houses ' + str(target_houses)}."
    )

    return {
        "event": event_name,
        "promise": f"{event_name} indicated during {md}-{ad}-{pd_lord} period" if md != "—" else "—",
        "best_period": best_period,
        "secondary": secondary,
        "key_planet": ad if ad != "—" else md,
        "trigger": pd_lord,
        "main_reason": main_reason,
        "risk": "Cross-check with D9/Navamsha and Ashtakoot before finalizing — remedy engine not yet connected.",
        "remedy": "—  (Vedic / Lal Kitab / gemstone remedy modules pending integration)",
        "confidence": confidence,
        "audit": {
            "MD": md,
            "AD": ad,
            "PD": pd_lord,
            "target_houses": target_houses,
            "core_houses": core_houses,
            "transit_score": total_score,
            "candidates_evaluated": len(D520_RANKED),
        },
    }


print("\n" + "=" * 76)
print("✅ build_universal_event_v1() READY")
print("=" * 76)
